/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A54 staging · exact frozen manifest indicate–informant (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('indicate','indicate 源自拉丁语 indicare（指出、表明），可用于显示事实、指点位置、示意转弯或表明治疗需要。',C('indicate.s1','设备检查','A flashing warning light may indicate that the machine needs servicing before it is used again.','警示灯闪烁可能表明机器需要检修后才能再次使用。','A flashing warning light / may indicate that the machine needs servicing / before it is used again.','indicate that 引出灯光所显示的情况；may 表示这是迹象而非绝对结论。','警示灯显示设备可能需要检修，符合 s1。'),M('The warning light indicated that the machine was safe even though the manual said it signaled a serious fault.','The warning light indicated that the machine had a fault and needed servicing.','手册说明该灯代表故障，不能解释为安全信号。'),[Q('indicate',1,1,'A result may indicate that?','something is true or exists','nothing can be learned','a person has been indicted','indicate 的 s1 表示显示或表明。'),Q('indicate',2,2,'To indicate a seat is to?','point to it or make a sign','bring it in from abroad','make it impossible to sit','s2 可表示指出或示意。'),Q('indicate',3,3,'When driving, indicate before?','turning','importing goods','writing a hymn','s3 指用信号灯示意转弯。'),Q('indicate',4,4,'A symptom may indicate?','that treatment is needed','that a vehicle should turn','that a report is an indictment','s4 表示症状表明需要治疗。')]);
P('indication','indication 经 indicate 加名词后缀 -ion 构成，表示表明情况或变化的迹象。',C('indication.s1','项目进度','A steady rise in completed applications is an indication that the new form is easier to use.','已完成申请数量稳步上升，说明新表格可能更容易使用。','A steady rise in completed applications / is an indication / that the new form is easier to use.','an indication that 引出迹象所支持的判断；steady rise 是该判断的依据。','申请完成数上升是表明表格更易用的迹象，符合 s1。'),M('The report called the rising completion rate an indication of lower use even though more people finished the form.','The report treated the rising completion rate as an indication of increased successful use.','完成率上升通常表明更多申请人顺利完成，而非使用率降低。'),[Q('indication',1,1,'An indication is?','a sign of something','a person who imports goods','a command form','indication 指迹象、信号。'),Q('indication',2,1,'A fever can be an indication of?','an illness or other condition','a person’s profession as an importer','an exact guarantee of one diagnosis','症状可能是疾病迹象，但不必然是唯一诊断。'),Q('indication',3,1,'Which phrase is natural?','an indication that the plan is working','an indication on the plan that working','an indication from working the plan that','常见结构是 indication that。'),Q('indication',4,1,'A steady improvement is an indication that?','conditions may be getting better','nothing has changed','a person is being indicted','变化可以作为当前状况的迹象。')]);
P('indicative','indicative 可表示显示或暗示某种状态的，也可作语法术语指陈述事实的语气。',C('indicative.s1','检查结果','A lower error rate is indicative of clearer instructions, although the team will review more data before deciding.','错误率降低表明说明文字可能更清楚，不过团队还会查看更多数据再作判断。','A lower error rate / is indicative of clearer instructions / although the team will review more data / before deciding.','be indicative of 表示是……的迹象；although 限定结论仍需更多数据。','错误率下降显示说明可能改善，符合 s1。'),M('The analyst called the lower error rate indicative of worse instructions while explaining that fewer mistakes had been made.','The analyst said the lower error rate was indicative of clearer instructions.','错误减少通常支持说明更清楚，而不是更差。'),[Q('indicative',1,1,'A result indicative of improvement?','shows or suggests improvement','rules out any possible change','is a person who reports facts','s1 表示表明或暗示。'),Q('indicative',2,2,'The indicative mood is used to?','state facts','give a direct order only','form an imported product','s2 是陈述语气。'),Q('indicative',3,1,'Which phrase is natural?','indicative of a change','indicative for a change of','indicative at changing','常见结构是 indicative of。'),Q('indicative',4,2,'“She works” is normally in the?','indicative mood','imperative mood','imperfect noun form','普通陈述句通常用陈述语气。')]);
P('indicator','indicator 由 indicate 加表示事物或人的后缀 -or 构成，指显示某种状态的迹象或指标。',C('indicator.s1','空气监测','The monitor’s color indicator turns orange when indoor particle levels rise above the recommended range.','室内颗粒物浓度超过建议范围时，监测器的颜色指示灯会变成橙色。','The monitor’s color indicator turns orange / when indoor particle levels rise / above the recommended range.','indicator 指显示状态的标志；when 从句说明橙色指示灯出现的条件。','颜色变化显示颗粒物水平，符合 s1。'),M('The manual called the orange light an indicator of normal levels even though it appears only when readings exceed the range.','The manual called the orange light an indicator of elevated readings.','超过范围时亮灯，表示水平升高而不是正常。'),[Q('indicator',1,1,'An indicator is?','a sign showing a state','a private opinion with no sign','a person who is always indifferent','indicator 指状态指标或标志。'),Q('indicator',2,1,'An orange indicator on a monitor may?','signal that a measured level is high','serve as the product’s importer','prove every reading is false','指示灯可显示测量状况。'),Q('indicator',3,1,'A falling unemployment rate could be an indicator of?','a change in the labor market','a vehicle’s turn signal','a written criminal charge','指标可显示某一领域的情况。'),Q('indicator',4,1,'The suffix -or in indicator often names?','something that performs or shows an action','a state of being poor','an adjective meaning not edible','-or 可构成执行或显示功能的名词。')]);
P('indict','indict 源自拉丁语 indictare，指由法律程序正式控告，也可引申为公开批评或谴责。',C('indict.s1','法律报道','A grand jury voted to indict the contractor, but the charge remains an allegation until resolved in court.','大陪审团投票决定起诉这名承包商，但在法院审结前，这项指控仍只是指控。','A grand jury voted to indict the contractor / but the charge remains an allegation / until resolved in court.','indict someone 是正式起诉；but 从句提醒起诉本身不等于定罪。','大陪审团提出正式刑事指控，符合 s1。'),M('The article said the contractor was indicted but also stated that no formal charge had been filed.','The article said the contractor was accused publicly but had not been formally indicted.','没有提出正式指控，就不应称为已被依法起诉。'),[Q('indict',1,1,'To indict someone is to?','officially charge them with a serious crime','find them guilty after trial','hire them as an importer','indict 指正式控告，不等于判罪。'),Q('indict',2,2,'A public editorial may indict a policy by?','criticizing or accusing it publicly','filing a formal criminal charge','showing a turn signal','s2 是公开指责。'),Q('indict',3,1,'Does an indictment itself prove guilt?','No, it is a formal charge, not a verdict.','Yes, every charge is a conviction.','No, it means the person was hired.','起诉不等于定罪。'),Q('indict',4,1,'Which body may vote to indict in a legal process?','a grand jury','a weather station','a traffic indicator','大陪审团可决定是否提出正式指控。')]);
P('indictment','indictment 可指启动刑事案件的正式书面起诉，也可比喻为表明某制度或行为糟糕的证据。',C('indictment.s1','司法程序','The indictment lists the charges filed against the company director and identifies the alleged dates and transactions.','起诉书列出了针对公司主管提出的指控，并注明涉嫌发生的日期和交易。','The indictment lists the charges / filed against the company director / and identifies the alleged dates / and transactions.','indictment 在此指正式起诉文件；alleged 表明指控尚待审理。','文件正式列出刑事指控，符合 s1。'),M('The report called a signed acquittal notice an indictment even though it formally cleared the defendant of the listed charges.','The report called the document an acquittal notice because it cleared the defendant.','宣告无罪的文件不是起诉书。'),[Q('indictment',1,1,'A legal indictment is?','an official written charge starting a criminal case','a final acquittal','a casual rumor','s1 指正式书面起诉。'),Q('indictment',2,2,'A report may call a failure an indictment of a system when it?','shows the system is deeply flawed','formally charges a person in court','serves as a turn signal','s2 是比喻义的严厉证据或谴责。'),Q('indictment',3,1,'Does an indictment list allegations or decide guilt?','It lists formal charges; a court decides guilt.','It always proves guilt immediately.','It names a company’s importer.','起诉书列指控，判决由法院作出。'),Q('indictment',4,2,'A poor safety record may be an indictment of?','the system responsible for safety','a specific grammatical mood','a new indicator light','失败记录可作为制度有问题的证据。')]);
P('indifference','indifference 源自拉丁语 indifferentia，表示对某事不关心、态度冷淡。',C('indifference.s1','志愿服务','The coordinator’s indifference to repeated requests for accessible seating frustrated visitors who needed it.','协调员对多次提出的无障碍座位请求漠不关心，让有需要的访客感到失望。','The coordinator’s indifference to repeated requests / frustrated visitors / who needed it.','indifference to 表示对某事漠不关心；who 从句说明受影响的访客。','协调员没有理会需求，符合 s1。'),M('The coordinator showed indifference by carefully listening to every request and arranging accessible seats immediately.','The coordinator showed concern by listening and arranging accessible seats.','积极倾听并迅速提供帮助表现出关心，不是冷漠。'),[Q('indifference',1,1,'Indifference is?','a state of not caring about something','strong anger at unfairness','a formal legal charge','indifference 指漠不关心。'),Q('indifference',2,1,'Indifference to a safety request means?','showing little or no concern about it','responding promptly and carefully','making the request more accessible','冷漠是缺少关心或回应。'),Q('indifference',3,1,'Which phrase is standard?','indifference to the problem','indifference for solving the problem of','indifference at problem to','常用搭配 indifference to。'),Q('indifference',4,1,'A close opposite of indifference is?','concern','apathy','unconcern','concern 表示关心。')]);
P('indigence','indigence 经拉丁语 indigentia 发展而来，指严重贫困或物质匮乏的状态。',C('indigence.s1','社会服务','The survey documented indigence in the district by recording households without reliable food, heat, or shelter.','调查通过记录缺少稳定食物、供暖或住所的家庭，呈现了该地区的贫困状况。','The survey documented indigence / in the district / by recording households / without reliable food, heat, or shelter.','indigence 是抽象名词，表示极度贫困；by 引出调查记录的依据。','家庭缺乏基本生活资源体现 s1。'),M('The report described a district with abundant housing, food, and income as a place of indigence.','The report described the well-resourced district as prosperous rather than indigent.','基本资源充足与贫困匮乏不符。'),[Q('indigence',1,1,'Indigence is?','the state of being very poor','a state of great wealth','a type of infection','indigence 指穷困。'),Q('indigence',2,1,'A report on indigence may examine?','lack of basic resources among households','the grammar of a sentence','how an indicator turns orange','贫困调查会记录基本资源短缺。'),Q('indigence',3,1,'Indigence is a noun related to?','indigent','indicative','indomitable','indigent 表示贫困的。'),Q('indigence',4,1,'Which conditions suggest indigence?','unreliable access to food and shelter','secure housing and ample income','an unexpectedly high harvest','基本生活资源短缺表明贫困。')]);
P('indigent','indigent 由拉丁语 indigere（需要、缺乏）相关词形发展而来，形容贫困到需要援助的。',C('indigent.s1','法律援助','The court appointed counsel for an indigent defendant who could not afford a lawyer.','法院为无力聘请律师的贫困被告指定了法律援助律师。','The court appointed counsel / for an indigent defendant / who could not afford a lawyer.','indigent 修饰 defendant，表示贫困、需要帮助；who 从句说明其经济困难。','被告无力承担律师费用，符合 s1。'),M('The applicant was called indigent even though she had ample savings and could easily pay for legal counsel.','The applicant was called financially secure because she had ample savings for legal counsel.','有充足储蓄、可负担法律服务的人不符合 indigent。'),[Q('indigent',1,1,'An indigent person is?','so poor as to need help','wealthy enough to fund others','unable to be identified visually','indigent 指穷困且需要援助的。'),Q('indigent',2,1,'Why may an indigent defendant receive appointed counsel?','they cannot afford a lawyer','they are already a judge','they imported the case','无力支付律师费用是获得指定律师的原因。'),Q('indigent',3,1,'Indigent describes?','a person or group in poverty','the abstract state of indifference','a court document','indigent 是形容词。'),Q('indigent',4,1,'A close opposite of indigent is?','financially well-off','poor','in need of help','financially well-off 与贫困相反。')]);
P('indigestible','indigestible 可指胃里难以消化的食物，也可比喻内容复杂枯燥而难以吸收的。',C('indigestible.s1','营养建议','The nutritionist suggested smaller portions of the rich, indigestible meal until the patient’s stomach settled.','营养师建议在患者胃部恢复前，少量食用这种油腻难消化的餐食。','The nutritionist suggested smaller portions / of the rich, indigestible meal / until the patient’s stomach settled.','indigestible 修饰 meal，表示身体难以消化；until 引出建议适用的时段。','油腻餐食难以消化，符合 s1。'),M('The meal was called indigestible even though it was light, easy on the stomach, and caused no digestive difficulty.','The meal was called easy to digest because it was light on the stomach.','容易消化的食物不应称为 indigestible。'),[Q('indigestible',1,1,'Indigestible food is?','not easily digested by the stomach','always absorbed immediately','a sign of poverty','s1 指难消化的。'),Q('indigestible',2,2,'An indigestible textbook may be?','too complicated or dull to absorb easily','easy to understand at a glance','a food that digests quickly','s2 是难理解或难吸收的比喻义。'),Q('indigestible',3,1,'Which food description fits the physical sense?','rich food that causes digestive discomfort','a light meal that is easy on the stomach','a paragraph with technical terms','s1 描写胃部消化。'),Q('indigestible',4,2,'Why might a report be called indigestible?','its dense presentation makes the ideas hard to absorb','it contains too few words','it is physically edible','比喻义关注信息难以理解。')]);
P('indigestion','indigestion 由否定前缀 in- 与 digestion 构成，指食物消化不良引起的胃部不适。',C('indigestion.s1','健康记录','After a very rich meal, Omar reported indigestion and asked the clinic whether he should avoid similar foods.','吃过一顿非常油腻的饭后，奥马尔出现消化不良，并询问诊所是否应避免类似食物。','After a very rich meal / Omar reported indigestion / and asked the clinic / whether he should avoid similar foods.','indigestion 是名词，表示胃部消化不适；after 引出症状出现的时间。','饭后胃部不适符合 s1。'),M('Omar called his stomach discomfort indigestion even though it was caused by a sprained ankle and involved no digestive symptoms.','Omar said the ankle pain was unrelated to digestion.','脚踝扭伤并非消化问题，不能称为 indigestion。'),[Q('indigestion',1,1,'Indigestion is?','stomach discomfort because food is not digested well','a formal accusation','anger about unfairness','indigestion 指消化不良。'),Q('indigestion',2,1,'When might someone report indigestion?','after a meal causes stomach discomfort','after a turn signal flashes','when a policy is implemented','胃部餐后不适符合该词。'),Q('indigestion',3,1,'The prefix in- in indigestion suggests?','a problem or lack in digestion','a strong degree of digestion','a person doing digestion','该词由否定前缀与 digestion 构成。'),Q('indigestion',4,1,'Which symptom is closest to indigestion?','an upset stomach after eating','a sore wrist after lifting','a fever from an infection','餐后胃部不适接近 indigestion。')]);
P('indignation','indignation 源自拉丁语 indignari（认为不配、感到愤慨），指对不公平之事的愤怒。',C('indignation.s1','社区会议','Residents expressed indignation when they learned that the only public bus route would be cut without consultation.','居民得知唯一的公共公交线路将在未经协商的情况下取消后，表达了愤慨。','Residents expressed indignation / when they learned / that the only public bus route / would be cut without consultation.','indignation 是对不公的愤怒；when 从句说明触发这种情绪的消息。','未经协商削减公共服务引发对不公的愤慨，符合 s1。'),M('The residents felt indignation about the fair process because everyone had been consulted and treated equally.','The residents felt gratitude about the fair process because everyone had been consulted.','公平且充分协商通常不会引发对不公的愤慨。'),[Q('indignation',1,1,'Indignation is anger at?','unfairness','a confusing manual','a sudden urge to shop','indignation 指对不公平的愤慨。'),Q('indignation',2,1,'What might cause public indignation?','a service cut imposed without consultation','a transparent process that treats everyone fairly','a routine change everyone requested','不公平、未经协商的决定可能引发愤慨。'),Q('indignation',3,1,'Indignation is stronger than simple?','indifference','concern about unfairness','anger at injustice','它与漠不关心相反，强调愤慨。'),Q('indignation',4,1,'Which phrase is natural?','express indignation at an unfair decision','indignation by a public bus route','an indignation to eat dinner','可说 express indignation at something。')]);
P('indignity','indignity 源自拉丁语 indignitas（不配、失去尊严），指羞辱或不尊重他人价值的对待。',C('indignity.s1','服务体验','Being made to explain her disability repeatedly at the public counter felt like an indignity to Mara.','玛拉在公共柜台被迫一再解释自己的残障，觉得这是一种有损尊严的对待。','Being made to explain her disability repeatedly / at the public counter / felt like an indignity / to Mara.','indignity 可用 an indignity to someone，指有辱尊严的事情；动名词短语作主语。','在公共场合反复被迫解释私密情况使人受辱，符合 s1。'),M('The staff called the private, respectful assistance an indignity even though Mara had requested it and felt respected.','The staff called the assistance respectful because Mara requested it and felt respected.','当事人主动请求且感到受尊重的帮助不是羞辱性对待。'),[Q('indignity',1,1,'An indignity is?','an act that humiliates or ignores someone’s worth','a sign of a mild illness','a fair treatment that protects dignity','indignity 指有损尊严的对待。'),Q('indignity',2,1,'Being publicly mocked for a personal condition may feel like?','an indignity','an indication','an induction','公开嘲弄会使人受辱。'),Q('indignity',3,1,'Which phrase is natural?','suffer an indignity','indignity into a person','indignity with imports','可说 suffer an indignity。'),Q('indignity',4,1,'A close opposite of indignity is?','respectful treatment','humiliation','an insult','尊重与羞辱相反。')]);
P('indirectly','indirectly 由 indirect 加副词后缀 -ly 构成，表示经由中间人、原因或路线，而非直接进行。',C('indirectly.s1','信息传递','The researcher learned indirectly from a colleague that the archive would close for repairs next week.','研究人员通过一位同事间接得知，档案馆下周将因维修关闭。','The researcher learned indirectly / from a colleague / that the archive would close / for repairs next week.','indirectly 修饰 learned，说明信息通过中间人传来；that 从句呈现消息内容。','研究者不是直接从档案馆获知，而是经同事转述，符合 s1。'),M('She learned indirectly from the director face-to-face in a direct one-to-one conversation.','She learned directly from the director in a face-to-face conversation.','一对一当面获知属于直接渠道。'),[Q('indirectly',1,1,'Indirectly means?','through an intermediate person, cause, or route','without any route or connection','in a loud and direct manner','indirectly 指间接地。'),Q('indirectly',2,1,'A colleague tells you what the director said; you learned?','indirectly','directly from the director','by imposing a rule','消息经同事传递属于间接获知。'),Q('indirectly',3,1,'Which sentence uses indirectly correctly?','The funds indirectly supported the clinic through a local charity.','She indirectly met the person face-to-face alone.','The report was indirectly a number.','资金经慈善组织转交，属于间接支持。'),Q('indirectly',4,1,'The adjective related to indirectly is?','indirect','indicative','indigence','indirectly 由 indirect 派生。')]);
P('indiscernible','indiscernible 由否定前缀 in- 与 discernible 构成，表示细微或隐蔽到无法感知、辨认。',C('indiscernible.s1','音频检验','The difference between the two recordings was indiscernible to most listeners without headphones.','如果不戴耳机，大多数听众都无法辨别这两段录音的差异。','The difference between the two recordings / was indiscernible to most listeners / without headphones.','indiscernible to someone 表示对某人难以察觉；without 引出辨别所需条件。','大多数人听不出细小差异，符合 s1。'),M('The difference was indiscernible even though every listener could identify it immediately without equipment.','The difference was readily discernible because every listener identified it at once.','人人都能立即辨认，就不是 indiscernible。'),[Q('indiscernible',1,1,'An indiscernible difference is?','so slight or hidden that it cannot be perceived','obvious to everyone immediately','a formal criminal charge','indiscernible 指难以察觉、辨认。'),Q('indiscernible',2,1,'Without headphones, the audio difference was indiscernible means listeners?','could not detect it','heard it clearly','created the recordings','indiscernible 描述无法听出。'),Q('indiscernible',3,1,'The prefix in- in indiscernible means?','not','very large','between two things','否定前缀形成“无法辨识”。'),Q('indiscernible',4,1,'A close opposite of indiscernible is?','noticeable','hidden','imperceptibly small','noticeable 表示能察觉。')]);
P('indiscreet','indiscreet 由否定前缀 in- 与 discreet（谨慎的）构成，形容言行不慎、尤其泄露秘密。',C('indiscreet.s1','保密沟通','It was indiscreet of the assistant to discuss the confidential schedule in a crowded elevator.','助理在拥挤的电梯里谈论保密日程，这样做不够谨慎。','It was indiscreet of the assistant / to discuss the confidential schedule / in a crowded elevator.','It was indiscreet of someone to do 表示某人的行为不谨慎；地点使泄密风险明显。','在公共场所谈论机密信息不慎重，符合 s1。'),M('The assistant acted indiscreetly by keeping the confidential schedule private and sharing it only with authorized staff.','The assistant acted discreetly by sharing the schedule only with authorized staff.','遵守保密原则是谨慎，不是 indiscreet。'),[Q('indiscreet',1,1,'An indiscreet comment is?','careless, especially about private or secret matters','careful to protect confidential information','impossible to hear','indiscreet 指言行不慎。'),Q('indiscreet',2,1,'Discussing a confidential schedule in a crowded elevator is?','indiscreet','indigent','indicative','公开谈机密信息不谨慎。'),Q('indiscreet',3,1,'Which is the opposite of indiscreet?','discreet','indiscriminate','improper','discreet 指谨慎、保密。'),Q('indiscreet',4,1,'An indiscreet person may?','reveal a secret without considering the consequences','keep sensitive information private','ask for legal counsel','不考虑后果而泄露秘密符合该义。')]);
P('indiscretion','indiscretion 来自 indiscreet 相关词形，指不谨慎的行为，尤其是造成尴尬或泄露秘密的举动。',C('indiscretion.s1','职场回顾','The employee regretted the indiscretion of forwarding a private message to the entire department.','员工后悔把一条私人消息转发给整个部门这一不慎之举。','The employee regretted the indiscretion / of forwarding a private message / to the entire department.','indiscretion of + 动名词说明不慎行为；forwarding 的对象范围过广。','把私信转发给无关同事泄露了隐私，符合 s1。'),M('The manager called the employee’s careful decision to keep a private message confidential an indiscretion.','The manager called the decision discreet because it kept the message confidential.','谨慎保密不是不慎行为。'),[Q('indiscretion',1,1,'An indiscretion is?','a careless act, often embarrassing or revealing a secret','a well-planned act of discretion','a sign of a mild illness','indiscretion 指鲁莽或不检点的行为。'),Q('indiscretion',2,1,'Forwarding a private message widely may be?','an indiscretion','an indication of good secrecy','an act of careful discretion','扩散私人信息可能造成尴尬或泄密。'),Q('indiscretion',3,1,'Which phrase is natural?','regret an indiscretion','impose an indiscretion to a person','indiscretion on the account of','可说 regret an indiscretion。'),Q('indiscretion',4,1,'Indiscretion is related to the adjective?','indiscreet','indigestible','indomitable','indiscretion 与 indiscreet 同词族。')]);
P('indiscriminate','indiscriminate 由否定前缀 in- 与 discriminate（区分、选择）构成，表示不仔细区分好坏或对象。',C('indiscriminate.s1','资源分配','The indiscriminate removal of trees damaged both invasive plants and the native trees that sheltered birds.','不加区分地砍树既破坏了入侵植物，也伤害了为鸟类遮蔽的本地树木。','The indiscriminate removal of trees / damaged both invasive plants / and the native trees / that sheltered birds.','indiscriminate 修饰 removal，表示不加选择；both ... and 强调好坏对象都受影响。','砍伐没有区分入侵种和本地树木，符合 s1。'),M('The crew used an indiscriminate method by carefully selecting only the invasive trees and protecting all native ones.','The crew used a selective method by targeting invasive trees and protecting native ones.','精确筛选对象恰好不是不加区分。'),[Q('indiscriminate',1,1,'Indiscriminate action?','does not choose carefully between different things','carefully distinguishes each relevant case','is a formal legal charge','indiscriminate 指不加选择、无差别。'),Q('indiscriminate',2,1,'An indiscriminate cut may harm?','both beneficial and harmful trees','only the intended invasive plants','no plants at all','不作区分会伤及好坏对象。'),Q('indiscriminate',3,1,'The prefix in- in indiscriminate means?','not','more than once','toward a person','否定前缀改变 discriminate 的意义。'),Q('indiscriminate',4,1,'A close opposite of indiscriminate is?','selective','random','unfocused','selective 表示经过选择。')]);
P('indiscriminately','indiscriminately 是 indiscriminate 的副词，表示以随机、不加区别的方式。',C('indiscriminately.s1','文件清理','The software should not delete files indiscriminately; it must check whether each folder contains archived work.','软件不应不加区分地删除文件；它必须检查每个文件夹是否存有归档工作。','The software should not delete files indiscriminately / it must check / whether each folder contains archived work.','indiscriminately 修饰 delete，表示没有仔细区分；should not 表达必要限制。','逐项检查是为了避免随机删除，符合 s1。'),M('The program deleted files indiscriminately by reviewing every folder and removing only confirmed duplicates.','The program deleted only confirmed duplicates after checking every folder.','检查后只删重复文件属于有选择的处理。'),[Q('indiscriminately',1,1,'To act indiscriminately is to act?','randomly without making careful distinctions','after carefully selecting each case','only when a court indicts someone','indiscriminately 指不分青红皂白地。'),Q('indiscriminately',2,1,'Deleting files indiscriminately means?','deleting without checking which ones matter','removing only verified duplicates','backing up every folder first','不检查内容就删除是不加区分地处理。'),Q('indiscriminately',3,1,'Which sentence uses indiscriminately correctly?','The pesticide was sprayed indiscriminately across the whole field.','The list was sorted individually one item at a time.','The judge indicted the witness formally.','整片喷洒未作选择，符合副词义。'),Q('indiscriminately',4,1,'The adjective form is?','indiscriminate','indiscretion','indirect','indiscriminately 由 indiscriminate 派生。')]);
P('indiscrimination','indiscrimination 由否定前缀 in- 与 discrimination 相关词形构成，指把不同事物一概而论、不加区别的性质。',C('indiscrimination.s1','分类规则','The committee criticized the indiscrimination of a policy that treated every application the same despite relevant differences in need.','委员会批评这项政策不加区分：尽管需求存在重要差异，它仍把所有申请一视同仁。','The committee criticized the indiscrimination of a policy / that treated every application the same / despite relevant differences in need.','indiscrimination 是抽象名词，指不作必要区分；that 从句说明政策如何表现这一性质。','政策忽略申请人需求差异而一概处理，符合 s1。'),M('The policy showed indiscrimination by carefully distinguishing applicants according to their relevant needs.','The policy showed discrimination among relevant cases because it treated applicants differently according to need.','依据相关需求仔细区分与 indiscrimination 的不加区别相反。'),[Q('indiscrimination',1,1,'Indiscrimination is?','the quality of treating different things as if they were the same','careful attention to meaningful differences','a feeling of anger at unfairness','indiscrimination 指无差别、不加区别。'),Q('indiscrimination',2,1,'A policy shows indiscrimination when it?','ignores relevant differences among cases','adapts decisions to relevant needs','uses a clear selection rule','无视相关差异符合该义。'),Q('indiscrimination',3,1,'Indiscrimination is related to?','indiscriminate','indigent','indication','indiscriminate 表示不加选择的。'),Q('indiscrimination',4,1,'Which example best illustrates indiscrimination?','giving every case the same result despite relevant differences','carefully reviewing each case’s circumstances','choosing among applicants using published criteria','一概处理不同情况体现不加区别。')]);
P('indisposition','indisposition 可指影响日常活动的轻微疾病，也可表示不情愿或不愿意做某事。',C('indisposition.s2','行政安排','The chair’s indisposition to reopen the vote meant the committee needed a new proposal before it would reconsider the issue.','主席不愿重新表决，这意味着委员会需要提出新方案后他才会重新考虑此事。','The chair’s indisposition to reopen the vote / meant the committee needed a new proposal / before it would reconsider the issue.','indisposition to do 表示不情愿做某事；before 引出重新考虑的条件。','主席表现出不愿重新表决的倾向，符合 s2。'),M('The chair showed an indisposition to reconsider the vote by eagerly asking the committee to reopen it at once.','The chair showed willingness to reconsider the vote by asking the committee to reopen it.','主动要求立即重开表决体现愿意，而不是不情愿。'),[Q('indisposition',1,1,'A mild indisposition is?','a minor illness that limits normal activity','a severe legal accusation','a mathematical inequality','s1 指轻微身体不适。'),Q('indisposition',2,2,'An indisposition to help means?','a reluctance to help','an eagerness to help','a sign that help is required','s2 表示不情愿。'),Q('indisposition',3,2,'Which phrase is natural?','an indisposition to reconsider','an indisposition into a vote','an indisposition for reconsidered','常见结构是 indisposition to do。'),Q('indisposition',4,1,'Someone missing a meeting because of a mild indisposition is?','unable to attend because of a minor illness','refusing to attend out of principle','being formally indicted','轻微病痛可能影响正常活动。')]);
P('indistinct','indistinct 由否定前缀 in- 与 distinct 构成，形容轮廓或声音不清楚、难以辨认的。',C('indistinct.s1','广播收听','The announcement was indistinct through the closed station doors, so passengers checked the display board for the platform number.','隔着关着的车站门，广播内容听不清楚，因此乘客查看了显示屏上的站台号。','The announcement was indistinct / through the closed station doors / so passengers checked the display board / for the platform number.','indistinct 修饰 announcement，表示声音不清；so 引出乘客采取的补充办法。','隔着门难以听清广播，符合 s1。'),M('The announcement was indistinct even though every word sounded sharp and clear to all passengers.','The announcement was clear because every word was easy to hear.','所有词都清晰可闻与 indistinct 相反。'),[Q('indistinct',1,1,'An indistinct sound is?','not sharply defined and hard to hear','perfectly clear and loud','a written charge','indistinct 可描述不清楚的声音。'),Q('indistinct',2,1,'An indistinct outline is?','hard to see clearly','easy to recognize in detail','a formal indication','轮廓不清楚时可称 indistinct。'),Q('indistinct',3,1,'Why did passengers check the board?','the announcement was difficult to hear','the announcement was perfectly clear','the board was an indictment','听不清广播，乘客查看显示屏。'),Q('indistinct',4,1,'A close opposite of indistinct is?','clear','blurred','unclear','clear 与 indistinct 相反。')]);
P('indistinguishable','indistinguishable 由否定前缀 in- 与 distinguishable 构成，表示无法与另一事物区分。',C('indistinguishable.s1','样品检测','Under ordinary lighting, the two fabric samples were indistinguishable, so the lab compared their fibers under a microscope.','在普通光线下，两块布料样本无法区分，因此实验室在显微镜下比较了纤维。','Under ordinary lighting / the two fabric samples were indistinguishable / so the lab compared their fibers / under a microscope.','indistinguishable 常用 indistinguishable from 表示与另一物难分；so 引出进一步检测。','普通照明下两样本难以分辨，符合 s1。'),M('The samples were indistinguishable even though their colors and labels were obviously different to everyone.','The samples were distinguishable because their colors and labels were obviously different.','明显不同的样本可以被区分。'),[Q('indistinguishable',1,1,'Two objects are indistinguishable if?','you cannot tell them apart','you can identify each one immediately','they are unrelated by definition','indistinguishable 指无法辨别。'),Q('indistinguishable',2,1,'Which test may help with indistinguishable fabric samples?','examining their fibers under magnification','mixing them without labels','ignoring all differences','进一步观察可能发现细微差异。'),Q('indistinguishable',3,1,'Which phrase is standard?','indistinguishable from one another','indistinguishable to each other from','indistinguishable among to one','常说 indistinguishable from。'),Q('indistinguishable',4,1,'A close opposite of indistinguishable is?','recognizably different','impossible to tell apart','indistinct','recognizably different 表示能够区分。')]);
P('indite','indite 是经中古英语和法语传入的较少见文学动词，现代指写成或创作文字。',C('indite.s1','文学创作','The poet indited a short letter to her former teacher, choosing every phrase with care.','诗人给以前的老师写了一封短信，认真斟酌每个措辞。','The poet indited a short letter / to her former teacher / choosing every phrase / with care.','indite 是及物动词，后接写成的文字；现在多见于文学或正式语境。','诗人创作书面文字，符合 s1。'),M('The biographer said the poet indited the letter by composing it aloud but never putting any words into writing.','The biographer said the poet dictated the letter aloud rather than inditing it in writing.','indite 指写成文字，不是仅仅口述。'),[Q('indite',1,1,'To indite a letter is to?','compose it in writing','formally charge someone','make an indistinct sound','indite 指写作、创作文字。'),Q('indite',2,1,'Indite is most likely to appear in?','literary or formal writing','everyday casual conversation only','a chemical formula','这是较少见的文学动词。'),Q('indite',3,1,'Which sentence uses indite correctly?','The author indited a careful reply.','The author indited the car to turn.','The author was indited of a letter.','indite 可直接接写成的文字。'),Q('indite',4,1,'The closest meaning of indite is?','write or compose','indict formally','distinguish by sight','indite 和 indict 拼写近似但含义不同。')]);
P('indium','indium 因光谱中醒目的靛蓝色谱线而得名，是用于焊料、显示屏和半导体的稀有软金属元素。',C('indium.s1','显示材料','The materials team selected an indium-based transparent coating to conduct electricity across the display.','材料团队选用一种含铟的透明涂层，让电流能够通过显示屏表面。','The materials team selected an indium-based transparent coating / to conduct electricity / across the display.','indium 是金属元素名；indium-based 修饰 coating，说明其材料成分。','含铟涂层在透明表面导电，符合该元素的材料用途。'),M('The lab described indium as a common liquid gas used only to flavor food.','The lab described indium as a soft metallic element used in materials such as solders and screens.','铟是金属元素，不是常见液态气体或调味品。'),[Q('indium',1,1,'Indium is?','a rare soft metallic element','a common flavoring gas','a type of textile fiber','indium 指化学元素铟。'),Q('indium',2,1,'Indium may be used in?','solders, screens, and semiconductors','only in animal feed','a religious hymn','词条列出焊料、显示屏和半导体用途。'),Q('indium',3,1,'The name indium refers to a spectral line with what color?','indigo blue','bright orange','colorless','其命名与靛蓝色谱线有关。'),Q('indium',4,1,'Which description is accurate?','a soft metal used in some electronic materials','a hard gas used in sound systems','a kind of plant disease','铟是软金属，可用于电子材料。')]);
P('individualism','individualism 由 individual 加 -ism 构成，指重视个人而非群体优先的社会或政治观念。',C('individualism.s1','政治思想','The essay contrasts individualism, which places value on personal choice, with systems that put collective goals first.','文章把重视个人选择的个人主义与优先考虑集体目标的制度作了对比。','The essay contrasts individualism / which places value on personal choice / with systems / that put collective goals first.','individualism 是政治或社会观念；which 从句解释其重视个人选择的倾向。','强调个人相对于群体的价值，符合 s1。'),M('The essay defined individualism as placing the group above every person and rejecting all personal choice.','The essay defined collectivism as placing group goals above individual choice.','把群体置于个人之上是相反的价值排序。'),[Q('individualism',1,1,'Individualism values?','the individual over the group','the group over every individual','a single industrial machine','individualism 强调个人价值。'),Q('individualism',2,1,'An individualist outlook may emphasize?','personal choice and independence','identical roles for everyone','the importation of goods','该观念重视个人选择。'),Q('individualism',3,1,'Individualism is a?','social or political outlook','physical metal element','verb for writing a letter','individualism 指观念或思想取向。'),Q('individualism',4,1,'The suffix -ism often signals?','a system of ideas or outlook','a person who performs an action','an adverb of manner','-ism 常构成思想体系或观念名称。')]);
P('individualistic','individualistic 由 individual 与 -istic 构成，形容偏重个人独立而非集体规则或统一做法的。',C('individualistic.s1','团队文化','The studio has an individualistic work culture: designers choose their own process but share results with the whole team.','这家工作室的文化强调个人自主：设计师自行选择工作方式，但会与团队分享成果。','The studio has an individualistic work culture / designers choose their own process / but share results / with the whole team.','individualistic 修饰 work culture，表示重视个人自主；but 补充这种自主仍与团队分享并存。','设计师有较多个人选择空间，符合 s1。'),M('The studio called its culture individualistic even though every designer had to follow an identical process with no personal choice.','The studio called its culture highly uniform because everyone followed the same process.','没有个人选择、人人完全相同不符合个人主义的特点。'),[Q('individualistic',1,1,'An individualistic approach favors?','personal independence over collective rules','complete obedience to one identical method','a rule for formal charges','individualistic 强调个人独立。'),Q('individualistic',2,1,'An individualistic studio culture may let designers?','choose their own process','use no personal judgment','avoid all responsibility','个人自主可体现在选择工作方式。'),Q('individualistic',3,1,'Individualistic is an?','adjective','noun for poverty','adverb meaning indirectly','individualistic 是形容词。'),Q('individualistic',4,1,'A close contrast to individualistic is?','collective and uniform','personally independent','distinctive','统一集体导向与其相反。')]);
P('individuality','individuality 由 individual 加 -ity 构成，指使某人或某物区别于其他对象的独特性格或特点。',C('individuality.s1','视觉设计','The redesign preserved the café’s individuality by keeping its hand-painted signs and locally made furniture.','重新设计保留了咖啡馆的个性，继续使用手绘招牌和本地制作的家具。','The redesign preserved the café’s individuality / by keeping its hand-painted signs / and locally made furniture.','individuality 是抽象名词，指独特性；by 引出保留个性的具体办法。','手绘招牌和本地家具让咖啡馆有别于其他场所，符合 s1。'),M('The renovation preserved the café’s individuality by removing every unique feature and replacing it with the same design as every chain store.','The renovation made the café more uniform by removing its unique features.','抹去特色、换成千篇一律的设计会削弱独特性。'),[Q('individuality',1,1,'Individuality is?','the character that makes a person or thing distinctive','a rule requiring everyone to be identical','a sign of indigestion','individuality 指个性或独特性。'),Q('individuality',2,1,'Which feature may preserve a café’s individuality?','its distinctive hand-painted signs','removing every unique detail','copying every chain store exactly','保留特色有助于保持独特性。'),Q('individuality',3,1,'Individuality is most closely related to?','distinctiveness','indifference','indigestion','distinctiveness 与独特性接近。'),Q('individuality',4,1,'The noun individuality is related to?','individual','indicate','indict','individuality 由 individual 派生。')]);
P('individualize','individualize 由 individual 加 -ize 构成，可指按个人情况调整方案，也可指给某物标出个体身份。',C('individualize.s1','学习计划','The tutor individualized the reading plan after learning which subjects interested each student and where they needed support.','了解每位学生感兴趣的科目和需要帮助的地方后，导师为他们分别调整了阅读计划。','The tutor individualized the reading plan / after learning which subjects interested each student / and where they needed support.','individualize 在此表示按个人需求调整；after learning 引出调整所依据的信息。','计划按学生兴趣和需求作了个性化调整，符合 s1。'),M('The tutor individualized every plan by giving all students the exact same assignments regardless of their needs.','The tutor standardized the plans by giving everyone the same assignments.','完全相同、无视个人需求是标准化而非个性化。'),[Q('individualize',1,1,'To individualize a plan is to?','adapt it to a particular person','make every version exactly the same','formally indict its user','individualize 可表示个性化调整。'),Q('individualize',2,1,'A school may individualize support by?','matching help to each learner’s needs','giving identical help without review','removing all student choices','按每位学生需要调整支持符合该义。'),Q('individualize',3,1,'Individualize can also mean to?','mark something as belonging to a particular individual','import it from another country','make it impossible to use','该动词也可指标明某物的个体身份。'),Q('individualize',4,1,'Which sentence uses individualize correctly?','The clinic individualized the plan for each patient.','The clinic individualize for the plan each patient.','The clinic indicted the plan individually.','individualize 后接按个人调整的对象。')]);
P('individually','individually 由 individual 加副词后缀 -ly 构成，表示把人或物分开、逐一处理。',C('individually.s1','申请审核','The reviewers considered each application individually rather than ranking candidates as one undifferentiated group.','评审人员逐份审查申请，而不是把所有候选人当作一个不加区分的群体排名。','The reviewers considered each application individually / rather than ranking candidates / as one undifferentiated group.','individually 修饰 considered，表示逐个分别审查；rather than 对比整体处理方式。','每份申请都被单独审查，符合 s1。'),M('The panel reviewed the applications individually by placing them in one pile and never examining any one separately.','The panel reviewed the applications collectively without examining each one separately.','没有逐份检查，就不是 individually。'),[Q('individually',1,1,'To review applications individually is to review them?','as separate items or people','all together as one undivided unit','only after importing them','individually 指逐个、分别地。'),Q('individually',2,1,'Which arrangement is individual review?','each form receives its own assessment','one score is assigned to every form without review','all forms are discarded unseen','逐份评估就是分别审查。'),Q('individually',3,1,'The adverb individually modifies?','how an action is done','the name of a metal element','a formal criminal charge','副词说明动作如何进行。'),Q('individually',4,1,'A close opposite of individually is?','collectively','separately','one by one','collectively 表示集体地。')]);
P('indolent','indolent 源自拉丁语 indolentem，历史上有“不痛”的意思；现代常指懒惰，也用于形容发展缓慢、少痛的疾病。',C('indolent.s2','医学描述','The physician’s note described the condition as indolent because it had progressed slowly and caused little pain.','医生记录将这种病况描述为发展缓慢、疼痛较轻的类型。','The physician’s note described the condition as indolent / because it had progressed slowly / and caused little pain.','indolent 修饰 condition，采用医学义；because 解释该描述所依据的特点。','发展缓慢且很少疼痛符合 s2；例句仅说明术语，不给出治疗建议。'),M('The report called the disease indolent even though it developed rapidly and caused severe pain from the start.','The report called the disease rapidly progressing and painful.','快速发展且剧痛与医学义 indolent 相反。'),[Q('indolent',1,1,'An indolent person is?','lazy or unwilling to make an effort','energetic and industrious','difficult to distinguish','s1 指懒惰的。'),Q('indolent',2,2,'An indolent disease tends to?','progress slowly and cause little pain','develop rapidly with severe pain','be impossible to identify by sight','s2 是发展慢、少痛的医学用法。'),Q('indolent',3,1,'Which behavior is indolent in the everyday sense?','avoiding effort despite having a task','working steadily to finish a task','carefully reviewing the evidence','懒于付出努力符合常见义。'),Q('indolent',4,2,'The medical sense of indolent describes?','the course and pain of a condition','a person’s legal status','an industrial policy','医学义形容病况进展与疼痛。')]);
P('indomitable','indomitable 由否定前缀 in- 与表示驯服、制服的词根构成，形容精神上无法击败或压服的。',C('indomitable.s1','体育精神','Despite a difficult recovery, the athlete showed indomitable resolve and returned to training gradually with her coach.','尽管康复过程艰难，这名运动员仍展现出不屈的决心，并在教练陪同下逐步恢复训练。','Despite a difficult recovery / the athlete showed indomitable resolve / and returned to training gradually / with her coach.','indomitable 修饰 resolve，表示不屈不挠；despite 表示困难并未压垮决心。','面对困境仍坚持前进，符合 s1。'),M('Her spirit was indomitable because she gave up immediately at the first setback and refused all support.','Her spirit was defeated by the setback because she gave up immediately.','立即放弃说明意志被挫折击垮，并非 indomitable。'),[Q('indomitable',1,1,'An indomitable spirit is?','impossible to defeat or subdue','easily discouraged and defeated','a kind of metal','indomitable 指不屈的、压不垮的。'),Q('indomitable',2,1,'Which response shows indomitable resolve?','continuing carefully after a setback','quitting at the first difficulty','refusing to consider any plan','挫折后继续努力体现不屈精神。'),Q('indomitable',3,1,'The prefix in- contributes the idea of?','not or inability','a person who does something','a state of being poor','否定前缀构成“无法制服”。'),Q('indomitable',4,1,'A close synonym for indomitable is?','unconquerable','easily subdued','indifferent','unconquerable 表示不可征服。')]);
P('inducible','inducible 由 induce 加 -ible 构成，表示能够被诱导、引发，常用于基因、酶或反应。',C('inducible.s1','分子生物学','The researchers measured an inducible enzyme response after exposing the cell culture to a controlled signal.','研究人员让细胞培养物接触一种受控信号后，测量了可诱导的酶反应。','The researchers measured an inducible enzyme response / after exposing the cell culture / to a controlled signal.','inducible 修饰 enzyme response，表示该反应能被特定条件引发；after 引出实验顺序。','反应由外界信号触发，符合 s1。'),M('The study called the response inducible even though no stimulus could ever trigger or increase it.','The study called the response non-inducible because no stimulus could trigger it.','无法被任何刺激引发的反应不是 inducible。'),[Q('inducible',1,1,'An inducible response is?','able to be triggered or brought about','impossible to cause under any condition','a person who performs induction','inducible 表示可被诱导或引发。'),Q('inducible',2,1,'An inducible gene may be activated by?','a particular signal or condition','no condition or stimulus at all','a written criminal charge','特定信号可诱导基因表达。'),Q('inducible',3,1,'The suffix -ible means roughly?','capable of being','already finished','without a person','-ible 表示能够被……。'),Q('inducible',4,1,'Which example fits inducible?','an enzyme response triggered by a controlled signal','a reaction that cannot occur under any condition','a fixed metal element','受信号触发的反应符合该义。')]);
P('induction','induction 可指正式引入某人进入职位或组织，也可指从个别事实归纳，或磁感应现象。',C('induction.s1','新员工入职','The induction for new museum guides includes a building tour, emergency procedures, and a meeting with the education team.','新博物馆讲解员的入职介绍包括参观建筑、学习应急流程，以及与教育团队会面。','The induction for new museum guides / includes a building tour / emergency procedures / and a meeting with the education team.','induction 在此指正式介绍新人进入岗位；includes 列出入职活动内容。','活动帮助新人进入工作岗位并熟悉组织，符合 s1。'),M('The museum’s induction excluded new guides from the organization and provided no introduction or orientation.','The museum’s induction introduced new guides to the organization and their duties.','排斥新人且不作介绍与入职引导的含义相反。'),[Q('induction',1,1,'An employee induction is?','a formal introduction to a job or organization','a criminal charge','a form of individualism','s1 指入职或组织引导。'),Q('induction',2,2,'Scientific induction may reason from?','particular facts to a general conclusion','a general rule to one guaranteed fact only','a person’s mood to a tax','归纳推理由个别事实得出一般结论。'),Q('induction',3,2,'Electromagnetic induction involves?','producing electricity through magnetism','introducing a new museum guide','the study of industrial society','s2 也包括电磁感应。'),Q('induction',4,1,'A welcome tour for new staff is part of?','their induction','an indictment','indigence','新人欢迎与培训属于入职引导。')]);
P('inductive','inductive 可指从具体观察推导一般结论的归纳过程，也可指与电磁感应有关的。',C('inductive.s1','科学推理','The students used inductive reasoning by comparing several local measurements before proposing a general pattern.','学生们先比较了几组本地测量数据，再提出一般规律，以此进行归纳推理。','The students used inductive reasoning / by comparing several local measurements / before proposing / a general pattern.','inductive 修饰 reasoning，表示从具体观察归纳一般结论；before 表明推理步骤。','从若干具体数据提出总体规律，符合 s1。'),M('The report called the reasoning inductive even though it began with a universal rule and applied it to one case.','The report called the reasoning deductive because it applied a general rule to one case.','从一般规则推至具体案例是演绎，不是归纳。'),[Q('inductive',1,1,'Inductive reasoning moves from?','specific observations toward a general conclusion','a general rule to a single case','a legal charge to a verdict','s1 指从具体到一般的归纳。'),Q('inductive',2,2,'An inductive coil is related to?','electromagnetic induction','a general social philosophy','a lack of effort','s2 指电磁感应相关。'),Q('inductive',3,1,'Which method is inductive?','noticing many samples share a trait and forming a general rule','starting from a rule and testing one example','guessing without observations','由多项观察归纳规则符合 s1。'),Q('inductive',4,2,'An inductive sensor may operate through?','electromagnetic effects','formal employee orientation','a metal’s indolence','inductive 可用于电磁技术。')]);
P('industrialisation','industrialisation 是 industrialise 的英式拼法加名词后缀 -ation，指社会或地区大规模发展工业。',C('industrialisation.s1','经济史','The industrialisation of the region accelerated after the railway connected its factories with the coastal port.','铁路把该地区的工厂与沿海港口连通后，当地工业化进程加快了。','The industrialisation of the region accelerated / after the railway connected its factories / with the coastal port.','industrialisation 是工业化过程的名词；after 引出加快发展的条件。','工厂规模扩大并形成工业发展，符合 s1；此处采用英式 -isation 拼法。'),M('The editor rejected industrialisation as a misspelling solely because it uses the British -isation ending.','The editor accepted industrialisation as the British spelling and industrialization as the US variant.','industrialisation 是有效英式拼法，不能仅因拼法差异判错。','usage'),[Q('industrialisation',1,1,'Industrialisation is?','the large-scale development of industry','the decline of all manufacturing','a kind of political indictment','industrialisation 指工业化。'),Q('industrialisation',2,1,'Which change suggests industrialisation?','factories grow and become central to a region’s economy','all factories close permanently','one household buys a tool','大规模工厂发展体现工业化。'),Q('industrialisation',3,1,'Is industrialisation a valid spelling?','Yes; it is the British spelling.','No; only industrialization is valid.','No; it means individualism.','-isation 是英式拼法，-ization 常见于美式。'),Q('industrialisation',4,1,'The related verb is?','industrialise','indite','induce','industrialisation 来自 industrialise。')]);
P('industrialism','industrialism 由 industrial 加 -ism 构成，指以机械化工业和工厂生产组织社会的理念或制度。',C('industrialism.s1','社会史课程','The course examines industrialism by tracing how factory production changed work, housing, and urban life.','课程通过追踪工厂生产如何改变劳动、住房和城市生活，研究工业主义。','The course examines industrialism / by tracing how factory production changed / work, housing, / and urban life.','industrialism 指围绕工业生产组织社会的体系；by tracing 说明课程的研究方式。','工厂生产重塑社会组织，符合 s1。'),M('The historian defined industrialism as a society with no mechanized industry or factory production.','The historian defined preindustrial society as one without mechanized industry or factory production.','没有机械工业的社会与 industrialism 的核心含义相反。'),[Q('industrialism',1,1,'Industrialism organizes society around?','mechanized industry and factory production','individual art shows only','the absence of manufacturing','industrialism 指以工业生产为中心的社会组织。'),Q('industrialism',2,1,'A historian studying industrialism might examine?','how factories changed work and cities','how a person is formally indicted','how a gene is inducible','工业主义影响工作和城市结构。'),Q('industrialism',3,1,'The suffix -ism often refers to?','a system or outlook','one individual actor','a verb in the past tense','-ism 常表示制度或思想体系。'),Q('industrialism',4,1,'Which example best fits industrialism?','a society centered on large-scale factory production','a village with no manufacturing','an isolated painting style','工厂生产是 industrialism 的中心。')]);
P('industrialist','industrialist 由 industrial 加 -ist 构成，指制造业企业的所有者或高级管理者。',C('industrialist.s1','商业史介绍','The industrialist invested in a new textile mill and appointed a local manager to oversee daily production.','这位实业家投资建设了一家新纺织厂，并任命当地经理监督日常生产。','The industrialist invested in a new textile mill / and appointed a local manager / to oversee daily production.','industrialist 指制造业企业的所有者或高级负责人；and 连接投资与管理安排。','投资并控制制造业工厂的人符合 s1。'),M('The biography called a person who owned no business and had no role in manufacturing an industrialist.','The biography called the factory owner an industrialist because he controlled a manufacturing business.','与制造业无关的人不符合 industrialist 的定义。'),[Q('industrialist',1,1,'An industrialist is?','an owner or senior controller of manufacturing industry','a worker who imports one package','a person who studies indigence','industrialist 指实业家、制造业企业主。'),Q('industrialist',2,1,'Which person is an industrialist?','an owner overseeing a large factory','a customer buying one shirt','a lawyer writing an indictment','制造业企业所有者符合该义。'),Q('industrialist',3,1,'The suffix -ist here identifies?','a person involved in an activity or field','a quality of being distinct','a noun for industrial development','-ist 可指从事某领域的人。'),Q('industrialist',4,1,'An industrialist may make decisions about?','factory investment and production','a patient’s indigestion','a formal induction ceremony','实业家负责制造业投资或生产。')]);
P('industrialization','industrialization 是 industrialize 的常见美式拼法加 -ation，表示地区工业大规模发展的过程。',C('industrialization.s1','地区发展','Industrialization brought new manufacturing jobs to the valley, while planners worked to protect nearby rivers from waste.','工业化为山谷地区带来了新的制造业岗位，同时规划者努力保护附近河流免受废弃物污染。','Industrialization brought new manufacturing jobs / to the valley / while planners worked / to protect nearby rivers from waste.','industrialization 是过程名词；while 表示工业发展与环境保护工作并行。','制造业规模和就业增长体现工业化；句子同时指出规划责任。'),M('The report called the growth of manufacturing industrialization but claimed it meant that industry had disappeared.','The report described industrialization as the growth of manufacturing industry.','工业化是工业发展而非工业消失。'),[Q('industrialization',1,1,'Industrialization is?','the large-scale development of industry','the end of all factories','an individual’s unique character','industrialization 指工业化。'),Q('industrialization',2,1,'A valley gains manufacturing jobs as factories expand; this may be?','industrialization','indigestion','indirection','工厂扩张和制造业就业增长体现工业化。'),Q('industrialization',3,1,'Industrialization and industrialisation are?','US and British spelling variants','unrelated words with opposite meanings','both incorrect spellings','industrialization 是美式常见拼法，industrialisation 是英式。','美英拼写差异不等于含义不同。'),Q('industrialization',4,1,'The verb related to industrialization is?','industrialize','indicate','indict','industrialization 来自 industrialize。')]);
P('industrialized','industrialized 是 industrialize 的过去分词形容词，形容工业在经济中占重要地位的。',C('industrialized.s1','区域经济','The industrialized district has a large manufacturing sector, though many residents also work in education and health services.','这个工业化地区拥有庞大的制造业部门，不过许多居民也从事教育和医疗服务。','The industrialized district has a large manufacturing sector / though many residents / also work in education / and health services.','industrialized 修饰 district，表示工业在当地经济中占重要地位；though 补充经济结构并非单一。','制造业是地区经济的重要组成部分，符合 s1。'),M('The region was called industrialized even though it had no manufacturing sector or industrial activity.','The region was called nonindustrial because it had no manufacturing activity.','没有工业活动的地区不能称为 industrialized。'),[Q('industrialized',1,1,'An industrialized economy has?','industry as a major part of its economy','no manufacturing at all','only small-scale home crafts','industrialized 指工业在经济中占重要地位。'),Q('industrialized',2,1,'Which region is industrialized?','one with a large manufacturing sector','one with no factories or industry','one defined only by its climate','制造业规模大符合该义。'),Q('industrialized',3,1,'Industrialized is related to the verb?','industrialize','individualize','indite','industrialized 是 industrialize 的过去分词。'),Q('industrialized',4,1,'Does industrialized mean every resident works in a factory?','No, industry is a major part but not the only part of the economy.','Yes, no other work can exist.','No, it means no industry exists.','该词不意味着经济只包含工厂岗位。')]);
P('industrially','industrially 由 industrial 加副词后缀 -ly 构成，表示通过工业方式或从工业角度。',C('industrially.s1','生产方式','The component is produced industrially in a controlled facility rather than assembled by hand in a small workshop.','这种零件是在受控工厂中以工业方式生产的，而不是在小作坊里手工组装。','The component is produced industrially / in a controlled facility / rather than assembled by hand / in a small workshop.','industrially 修饰 produced，说明生产方式；rather than 对比工业生产与手工制作。','零件通过工业设施生产，符合 s1。'),M('The parts were produced industrially by one craftsperson at home without machines or a production facility.','The parts were produced by hand in a home workshop rather than industrially.','家庭手工制作不是通过工业方式生产。'),[Q('industrially',1,1,'Industrially means?','by means of industry or from an industrial point of view','one item at a time as separate people','with no production method','industrially 指以工业方式或从工业角度。'),Q('industrially',2,1,'A product made industrially is likely made?','in a controlled production facility','by a single person entirely by hand','without any manufacturing process','工厂生产符合 industrially。'),Q('industrially',3,1,'Industrially is an?','adverb','adjective for poverty','noun for an industry owner','-ly 使其作副词。'),Q('industrially',4,1,'Which sentence uses industrially correctly?','The material is industrially processed before shipping.','The industrially means a factory owner.','She industrially the report.','industrially 修饰 processed 表示加工方式。')]);
P('inedible','inedible 由否定前缀 in- 与 edible 构成，表示不适合或不安全食用的。',C('inedible.s1','野外采集','The guide warned the hikers that the bright berries were inedible and should be left untouched.','向导提醒徒步者，这些颜色鲜艳的浆果不宜食用，应当不要触碰。','The guide warned the hikers / that the bright berries were inedible / and should be left untouched.','inedible 修饰 berries，表示不适合食用；that 从句传达警告内容。','向导明确说明浆果不能安全食用，符合 s1。'),M('The guide called the berries inedible and then advised everyone to eat them freely.','The guide called the berries edible and safe to eat.','警告不能食用却又建议随意吃，前后矛盾。'),[Q('inedible',1,1,'Inedible food is?','not suitable or safe to eat','ready to eat safely','very easy to digest','inedible 指不宜食用的。'),Q('inedible',2,1,'A guide says wild berries are inedible; hikers should?','avoid eating them','collect and eat them immediately','use them as a traffic indicator','不宜食用的浆果应避免入口。'),Q('inedible',3,1,'The prefix in- in inedible means?','not','more than enough','a person who eats','否定前缀使 edible 变为不可食用。'),Q('inedible',4,1,'A close opposite of inedible is?','edible','unsafe','indigestible','edible 表示可食用。')]);
P('ineffective','ineffective 由否定前缀 in- 与 effective 构成，表示未能达到预期效果的。',C('ineffective.s1','项目复盘','The first reminder system was ineffective because most participants never received the messages on time.','第一套提醒系统没有效果，因为大多数参与者都没能及时收到消息。','The first reminder system was ineffective / because most participants / never received the messages / on time.','ineffective 作表语，表示未实现预期作用；because 说明原因。','参与者没有及时收到提醒，系统未达到目的，符合 s1。'),M('The reminder system was ineffective even though every participant received a timely reminder and completed the task.','The reminder system was effective because everyone received the reminder and completed the task.','提醒及时送达并促成完成，说明系统有效。'),[Q('ineffective',1,1,'An ineffective method?','fails to achieve its intended result','always succeeds as intended','is a person with no authority','ineffective 指无效的。'),Q('ineffective',2,1,'Why was the reminder system ineffective?','most people did not receive messages on time','every message arrived promptly','the task had already been completed','未及时送达导致未实现提醒目的。'),Q('ineffective',3,1,'The prefix in- in ineffective means?','not','again','together','否定前缀使其表示无效。'),Q('ineffective',4,1,'A close opposite of ineffective is?','effective','useless','unsuccessful','effective 表示有效。')]);
P('inefficiency','inefficiency 由否定前缀 in- 与 efficiency 构成，指浪费资源或工作效果不佳的状态。',C('inefficiency.s1','流程改进','The audit found inefficiency in the approval process because three offices repeatedly checked the same form.','审计发现审批流程效率低下，因为三个办公室反复检查同一份表格。','The audit found inefficiency in the approval process / because three offices / repeatedly checked the same form.','inefficiency 是抽象名词；because 引出浪费重复工作的具体原因。','重复审核浪费时间和人力，符合 s1。'),M('The audit reported inefficiency even though each form was reviewed once and the process used no excess resources.','The audit reported an efficient process because each form was reviewed once without waste.','没有重复或资源浪费不构成 inefficiency。'),[Q('inefficiency',1,1,'Inefficiency is?','wasteful or poor working performance','excellent use of time and resources','a lack of access to a vote','inefficiency 指低效或资源浪费。'),Q('inefficiency',2,1,'Three offices checking the same form may cause?','inefficiency','industrialization','infallibility','重复劳动造成低效。'),Q('inefficiency',3,1,'Inefficiency is related to?','inefficient','inevitable','indomitable','inefficient 表示低效的。'),Q('inefficiency',4,1,'Which situation shows inefficiency?','a task is duplicated and wastes staff time','one check is completed accurately','resources are saved without reducing quality','重复任务浪费时间，符合该义。')]);
P('inefficient','inefficient 由否定前缀 in- 与 efficient 构成，形容无法以较少浪费取得良好结果的。',C('inefficient.s1','办公流程','The old filing method was inefficient: staff searched several cabinets each time they needed a single record.','旧的归档方法效率很低：员工每次只找一份记录，却要翻查好几个文件柜。','The old filing method was inefficient / staff searched several cabinets / each time they needed / a single record.','inefficient 修饰 method；冒号后说明耗时低效的具体表现。','为单份记录反复翻柜子造成不必要浪费，符合 s1。'),M('The method was inefficient because it retrieved every record instantly and required almost no effort.','The method was efficient because it retrieved records quickly with little effort.','快速准确且耗费很少说明高效。'),[Q('inefficient',1,1,'An inefficient process?','wastes resources or fails to produce good results','uses resources carefully and succeeds','is always impossible to perform','inefficient 指低效的。'),Q('inefficient',2,1,'Searching several cabinets for one file is?','inefficient','a form of induction','an indicator of infallibility','重复翻找浪费时间。'),Q('inefficient',3,1,'The prefix in- in inefficient expresses?','not','very','again','否定前缀构成 not efficient。'),Q('inefficient',4,1,'Which process is more efficient?','a searchable index that finds the file quickly','several cabinets searched repeatedly','a filing method that loses records','快速检索且少浪费更高效。')]);
P('inelastic','inelastic 可表示材料不易拉伸或对刺激僵硬，也可指价格变化时需求或供应改变很少。',C('inelastic.s2','经济学讨论','Demand for the essential medicine remained inelastic when its price rose slightly, with patients buying nearly the same amount.','这种必需药品涨价少许后，需求仍缺乏弹性，患者购买量几乎没有变化。','Demand for the essential medicine remained inelastic / when its price rose slightly / with patients buying nearly the same amount.','inelastic 在此为经济学义，表示数量对价格变化反应很小；when 引出价格变化。','价格略涨而购买量几乎不变，符合 s2。'),M('The report called demand inelastic even though every small price increase caused customers to stop buying it entirely.','The report called demand highly elastic because purchases changed sharply with price.','购买量随价格剧烈变化是弹性高，不是缺乏弹性。'),[Q('inelastic',1,1,'An inelastic material?','does not stretch and return easily','stretches readily and springs back','is impossible to recognize','s1 指材料不易伸展。'),Q('inelastic',2,2,'In economics, inelastic demand changes?','little when price changes','dramatically with every small price change','only when the product is imported','s2 指需求对价格变化反应小。'),Q('inelastic',3,2,'If medicine purchases stay nearly the same after a small price rise, demand is?','inelastic','highly elastic','indistinct','数量变化小符合经济学义。'),Q('inelastic',4,1,'The closest opposite of inelastic material is?','stretchy and elastic','rigid','indistinguishable','elastic 表示有弹性的。')]);
P('ineligible','ineligible 由否定前缀 in- 与 eligible 构成，可指没有资格的人或不符合条件的。',C('ineligible.s1','奖学金申请','Applicants who have already received the award are ineligible to apply for it again this year.','已经获得过该奖项的申请者今年没有资格再次申请。','Applicants who have already received the award / are ineligible / to apply for it again this year.','ineligible to do 表示没有资格做某事；who 从句限定所指申请者。','规则排除已获奖者再次申请，符合 s1。'),M('The committee called every qualified applicant ineligible even though each one met all published requirements.','The committee called the applicants eligible because they met all published requirements.','符合所有资格条件的人不应称为不合格。'),[Q('ineligible',1,1,'An ineligible applicant?','does not have the right to apply or qualify','meets every selection rule','has already been selected automatically','ineligible 表示不具备资格。'),Q('ineligible',2,2,'An ineligible is?','a person who does not meet selection rules','a rule that all applicants meet','a formal written indictment','该词也可作名词指不合格者。'),Q('ineligible',3,1,'Which phrase is natural?','ineligible to vote','ineligible for voted','ineligible to voting','常用结构是 ineligible to do。'),Q('ineligible',4,1,'The prefix in- in ineligible means?','not','extremely','between','否定前缀表示不符合资格。')]);
P('inept','inept 源自拉丁语 ineptus（不合适、笨拙），形容缺少技能而导致结果不佳或尴尬的。',C('inept.s1','演示培训','The inept demonstration confused the trainees because the presenter skipped several steps and used the wrong settings.','这场笨拙的演示让学员困惑，因为演示者跳过了好几个步骤，还用了错误设置。','The inept demonstration confused the trainees / because the presenter skipped several steps / and used the wrong settings.','inept 修饰 demonstration，表示缺少技能、效果不佳；because 解释其原因。','跳步并使用错误设置体现演示能力不足，符合 s1。'),M('The presenter was called inept even though the demonstration was clear, accurate, and easy for everyone to follow.','The presenter was called capable because the demonstration was clear and accurate.','清晰准确、人人易懂的演示不体现 inept。'),[Q('inept',1,1,'An inept performance is?','awkward or poor because of a lack of skill','skillful and effective','difficult to distinguish visually','inept 指笨拙、不胜任。'),Q('inept',2,1,'Why was the demonstration inept?','it skipped steps and used wrong settings','it was clear and accurate','it followed every procedure correctly','错误操作导致表现不佳。'),Q('inept',3,1,'A close synonym for inept is?','clumsy','capable','effective','clumsy 表示笨拙。'),Q('inept',4,1,'Inept is an?','adjective','abstract noun for fairness','verb meaning to induct','inept 是形容词。')]);
P('inequality','inequality 可指财富、权利或待遇上的不公平差异，也可指数学中两个表达式大小不等的关系。',C('inequality.s1','社会研究','The report measures inequality in access to health care by comparing waiting times across neighborhoods.','报告通过比较不同社区的候诊时间，衡量医疗服务可及性方面的不平等。','The report measures inequality in access to health care / by comparing waiting times / across neighborhoods.','inequality in 表示某领域的不平等；by 引出测量方法。','不同社区获得医疗服务的等待时间存在不公平差异，符合 s1。'),M('The report called access equal even though one neighborhood waited ten times longer than another.','The report identified inequality because one neighborhood waited much longer than another.','服务等待时间差异巨大，不符合机会平等。'),[Q('inequality',1,1,'Social inequality is?','an unfair difference in wealth, rights, or treatment','a relation showing one number is greater than another','a state of having no energy','s1 指社会不平等。'),Q('inequality',2,2,'In mathematics, an inequality shows?','one expression is greater or less than another','two expressions are exactly equal','a person lacks eligibility','s2 是数学关系。'),Q('inequality',3,1,'Different health-care waiting times across neighborhoods may show?','inequality in access','a mathematical induction','indigestion','服务机会差异可能体现不平等。'),Q('inequality',4,2,'Which symbol often appears in an inequality?','<','+ only as an equality sign','a question mark only','小于号可表示不等关系。')]);
P('inequity','inequity 由否定前缀 in- 与 equity（公平）相关词形构成，指不公正或不公平的处境。',C('inequity.s1','公共服务','The inequity in school funding left rural students with fewer science materials than students in nearby towns.','学校经费分配不公，使农村学生拥有的科学教材少于附近城镇的学生。','The inequity in school funding / left rural students with fewer science materials / than students / in nearby towns.','inequity 常用 inequity in 表示某领域的不公；left ... with 描述造成的结果。','不同地区获得的教育资源不公平，符合 s1。'),M('The report found inequity even though every school received the same resources and students had equal access.','The report found no inequity because resources and access were equal.','资源与机会相同，不支持存在不公的结论。'),[Q('inequity',1,1,'Inequity is?','injustice or an unfair situation','a neutral mathematical relation only','a mild stomach illness','inequity 指不公正、不公平。'),Q('inequity',2,1,'A funding inequity may leave some schools with?','fewer resources than comparable schools','exactly equal resources in every case','no difference in access','资源分配差距可能体现不公。'),Q('inequity',3,1,'Inequity is especially close to?','injustice','indifference','induction','injustice 与不公正接近。'),Q('inequity',4,1,'Which phrase is natural?','inequity in access to education','inequity to access education of','an inequity by educating','常用结构 inequity in。')]);
P('inert','inert 可指静止、缺乏活力，也可指化学性质不活泼、不易参与反应的。',C('inert.s2','化学实验','Argon is chemically inert under the conditions used in this demonstration, so it does not readily react with the sample.','在这次演示所用条件下，氩的化学性质不活泼，因此不容易与样品发生反应。','Argon is chemically inert / under the conditions used in this demonstration / so it does not readily react / with the sample.','inert 在此为化学义；so 引出不易反应的结果。','氩在相关条件下不易参加化学反应，符合 s2。'),M('The gas was called chemically inert even though it reacted readily with the sample under the same conditions.','The gas was called chemically reactive because it readily reacted with the sample.','容易发生反应与化学惰性相反。'),[Q('inert',1,1,'An inert object in the everyday sense is?','not moving and seeming without energy','moving rapidly with great force','impossible to distinguish','s1 指静止、呆滞。'),Q('inert',2,2,'A chemically inert gas?','does not readily take part in a reaction','reacts immediately with every material','is always a solid metal','s2 指化学性质不活泼。'),Q('inert',3,2,'Argon is described in the example as inert because it?','does not readily react with the sample','changes color instantly','moves without energy','例句说明它不易发生化学反应。'),Q('inert',4,1,'Which scene fits the nonchemical sense of inert?','a motionless machine with no activity','a lively crowd running','a chemical reaction speeding up','静止且无活力符合日常义。')]);
P('inescapable','inescapable 由否定前缀 in- 与 escape、-able 构成，表示注定会发生或无法回避的。',C('inescapable.s1','项目复盘','Once the contract’s review date passed, a decision became inescapable because the funding window was closing.','合同审查日期一过，决定就无法再回避，因为资助期限即将结束。','Once the contract’s review date passed / a decision became inescapable / because the funding window / was closing.','inescapable 作表语形容词，表示无法逃避；because 说明为何必须作出决定。','期限迫近使决定不可避免，符合 s1。'),M('The committee called the deadline inescapable even though it could be postponed indefinitely without consequence.','The committee called the deadline avoidable because it could be postponed indefinitely.','可以无限期推迟、毫无后果就不是不可避免。'),[Q('inescapable',1,1,'An inescapable event is?','certain to be faced with no way out','easy to avoid','a mild illness','inescapable 指不可避免的。'),Q('inescapable',2,1,'If a decision is inescapable, the team?','cannot avoid making it','may ignore it forever','has already made no decision','该词强调没有回避途径。'),Q('inescapable',3,1,'The prefix in- in inescapable means?','not','very much','between two people','in- 是否定前缀。'),Q('inescapable',4,1,'A close synonym of inescapable is?','unavoidable','optional','indistinct','unavoidable 意为不可避免。')]);
P('inevitably','inevitably 由 inevitable 加副词后缀 -ly 构成，表示某事必定发生、无法避免地发生。',C('inevitably.s1','工程计划','If maintenance is postponed for too long, small faults inevitably become more expensive to repair.','如果维护拖延太久，小故障不可避免地会变得更难修、成本更高。','If maintenance is postponed for too long / small faults inevitably become / more expensive to repair.','inevitably 修饰 become，表示结果确定会出现；if 引出发生条件。','长期拖延维护会让小故障最终变贵，符合 s1。'),M('The report said the faults would inevitably worsen but also claimed they could never change or become more serious.','The report said the faults might worsen if maintenance continued to be delayed.','称其必然恶化又称绝不会变化，逻辑矛盾。'),[Q('inevitably',1,1,'Inevitably means?','as is certain to happen and cannot be avoided','by chance and with no certainty','so quietly that no one notices','inevitably 表示不可避免地。'),Q('inevitably',2,1,'If costs inevitably rise, will they rise?','They are certain to rise.','They might or might not rise.','They have already disappeared.','该副词表示结果必然发生。'),Q('inevitably',3,1,'Which sentence uses inevitably correctly?','Without upkeep, wear inevitably increases over time.','The wheel inevitably is a person.','She inevitable finished it yesterday.','inevitably 修饰结果 increases。'),Q('inevitably',4,1,'The adjective related to inevitably is?','inevitable','indolent','ineligible','inevitably 由 inevitable 派生。')]);
P('inexplicable','inexplicable 由否定前缀 in- 与 explicable 构成，表示奇怪到没有合理解释的。',C('inexplicable.s1','设备记录','The sensor showed an inexplicable drop in temperature even though the room settings and power supply had not changed.','尽管房间设置和电源都没变化，传感器仍显示温度莫名下降。','The sensor showed an inexplicable drop in temperature / even though the room settings / and power supply / had not changed.','inexplicable 修饰 drop，表示无法解释；even though 排除两个可能原因。','在已知条件不变时出现无法说明的降温，符合 s1。'),M('The temperature drop was inexplicable even though a technician immediately found and documented the broken thermostat that caused it.','The temperature drop was explained by the broken thermostat.','原因已被发现和记录，就不再是无法解释。'),[Q('inexplicable',1,1,'An inexplicable event?','has no reasonable explanation known','has an obvious documented cause','is certain to happen','inexplicable 指无法解释的。'),Q('inexplicable',2,1,'A sensor reading is inexplicable when?','it changes for no known reason','a technician finds the cause','it matches the expected value','没有合理原因可说明变化。'),Q('inexplicable',3,1,'The prefix in- in inexplicable means?','not','very','after','它否定 explicable，表示不可解释。'),Q('inexplicable',4,1,'A close opposite of inexplicable is?','understandable','unexplained','mysterious','understandable 表示能够理解或解释。')]);
P('inextricably','inextricably 由 inextricable 加 -ly 构成，表示紧密纠缠到无法分开的程度。',C('inextricably.s1','城市规划','The history of the harbor is inextricably linked to the growth of the neighborhoods built around it.','港口的历史与周边社区的发展紧密相连、难以分开。','The history of the harbor / is inextricably linked / to the growth of the neighborhoods / built around it.','inextricably 常与 linked 组成 inextricably linked，表示密不可分；to 引出关联对象。','港口与周边社区历史交织，符合 s1。'),M('The two histories were inextricably linked even though they had no shared events, places, or influence.','The two histories were unrelated because they shared no events or influence.','没有共同事件或影响就不构成无法分割的联系。'),[Q('inextricably',1,1,'Inextricably linked means?','so closely connected that separation is impossible','connected only by a loose coincidence','completely unrelated','inextricably 表示密不可分地。'),Q('inextricably',2,1,'The harbor’s history is inextricably linked to the city when?','their development has shaped each other','they share no events or influence','one began after the other vanished','相互影响说明两者紧密关联。'),Q('inextricably',3,1,'Which phrase is common?','inextricably linked','inextricably alone from','inextricably unrelatedly with','常见搭配 inextricably linked。'),Q('inextricably',4,1,'The adjective form is?','inextricable','inevitable','indistinct','inextricably 源自 inextricable。')]);
P('infallible','infallible 由否定前缀 in- 与 fallible 构成，表示不会出错或失败的；实际评价中常强调并无绝对无误的方法。',C('infallible.s1','质量审查','No checklist is infallible, so the engineers also inspect the finished device and record any overlooked fault.','没有哪份清单能保证绝无错误，因此工程师还会检查成品并记录任何遗漏故障。','No checklist is infallible / so the engineers also inspect the finished device / and record any overlooked fault.','infallible 作表语，表示绝无错误；No ... is infallible 是对“绝对无误”的限定。','工程师通过二次检查承认清单可能遗漏，符合 s1。'),M('The team called its checklist infallible even though it had repeatedly missed documented safety faults.','The team called its checklist fallible because it had missed documented faults.','反复漏掉已记录故障说明清单可能出错。'),[Q('infallible',1,1,'An infallible method?','cannot make a mistake or fail','fails on every attempt','is impossible to understand','infallible 指不会出错或失败。'),Q('infallible',2,1,'Why inspect a product even after using a checklist?','no checklist is guaranteed to be infallible','every checklist always catches everything','inspection is an importation','清单可能漏项，复查可发现问题。'),Q('infallible',3,1,'The prefix in- in infallible means?','not','more than once','toward a person','否定 fallible 构成“不会出错”。'),Q('infallible',4,1,'A close opposite of infallible is?','fallible','perfect','certain','fallible 表示可能犯错。')]);
P('infamatory','词库将 infamatory 登记为“煽动敌意或攻击名誉”的形容词；拼写沿革未确认，因此不推断其词源细节。',C('infamatory.s1','书面评论','The editor removed an infamatory claim about the volunteer because it attacked her reputation without supporting evidence.','编辑删去了一条针对志愿者的中伤性说法，因为它在没有证据的情况下损害了她的名誉。','The editor removed an infamatory claim / about the volunteer / because it attacked her reputation / without supporting evidence.','infamatory 修饰 claim，依词库释义表示煽动敌意或损害名誉；because 说明删改原因。','无证据攻击个人名誉符合 s1；此处保留词库登记拼写。'),M('The article called its praise infamatory even though it calmly celebrated the volunteer and damaged no one’s reputation.','The article called the unsupported personal attack infamatory because it damaged the volunteer’s reputation.','赞扬且没有损害名誉不符合词库登记的贬损性含义。'),[Q('infamatory',1,1,'According to this entry, an infamatory claim?','arouses hostility or attacks someone’s reputation','praises someone without criticism','describes a neutral measurement','词库释义包括煽动敌意或攻击名誉。'),Q('infamatory',2,1,'Why remove the infamatory claim in the example?','it harmed a person’s reputation without evidence','it carefully documented a public fact','it indicated a temperature change','无证据损害名誉是删改原因。'),Q('infamatory',3,1,'Which word is used as the exact headword here?','infamatory','inflammatory','infantile','清单和登记词条均为 infamatory，按原拼写处理。'),Q('infamatory',4,1,'A statement that inflames hostility toward a person fits?','the dictionary sense of infamatory','indigence','infallibility','煽动敌意符合该词条给出的意义。')]);
P('infancy','infancy 源自拉丁语 infantia，可指人的婴儿期，也可指新事物刚开始发展的阶段。',C('infancy.s2','技术发展','In its infancy, the community radio project had only a small team and broadcast for one hour each week.','在发展初期，这个社区广播项目只有一支小团队，每周播出一小时。','In its infancy / the community radio project had only a small team / and broadcast / for one hour each week.','in its infancy 是固定表达，表示处于萌芽阶段；and 并列介绍早期规模和活动。','项目刚起步，符合 s2。'),M('The project was described as being in its infancy after it had operated nationally for fifty years.','The project was described as mature after operating nationally for fifty years.','运行五十年并覆盖全国的项目不是刚起步。'),[Q('infancy',1,1,'Human infancy is?','the time of life when a child is a baby','the final stage of adulthood','a legal charge','s1 指婴儿期。'),Q('infancy',2,2,'A project in its infancy is?','at a very early stage','fully mature and long established','impossible to implement','s2 指新事物的初期。'),Q('infancy',3,2,'A community project broadcasts one hour weekly with a small team; it may be?','in its infancy','industrialized','infallible','规模小、刚起步符合萌芽阶段义。'),Q('infancy',4,1,'Infancy is related to the noun?','infant','indication','indictment','infancy 与 infant 同词族。')]);
P('infantile','infantile 可指婴幼儿的或幼儿期特有的，也可贬义地表示幼稚、孩子气。',C('infantile.s2','同伴交流','The reviewer called the prank infantile because it relied on childish name-calling rather than a clever joke.','评论者称这个恶作剧很幼稚，因为它只靠孩子气的辱骂，而不是巧妙的笑料。','The reviewer called the prank infantile / because it relied on childish name-calling / rather than a clever joke.','infantile 在此是贬义义项“幼稚”；because 说明评价依据。','低幼辱骂而非机智幽默符合 s2。'),M('The critic called the mature, thoughtful discussion infantile even though it involved no childish behavior.','The critic called the discussion thoughtful because it showed mature reasoning.','成熟而有理据的讨论不符合幼稚行为的描述。'),[Q('infantile',1,1,'Infantile behavior in the literal sense is?','typical of babies or very young children','typical of a factory owner','a condition of low prices','s1 指婴儿或幼儿的。'),Q('infantile',2,2,'An infantile joke may be?','silly in a childish way','carefully reasoned and mature','a mathematical inequality','s2 是贬义的“幼稚”。'),Q('infantile',3,2,'Why did the reviewer call the prank infantile?','it used childish name-calling instead of wit','it showed careful adult judgment','it was a medical condition','低幼辱骂符合贬义义项。'),Q('infantile',4,1,'Which phrase uses the literal sense?','an infantile reflex in a baby','an infantile industrial policy','an infantile criminal charge','婴儿的反射动作属于字面义。')]);
P('infatuate','infatuate 源于拉丁语 infatuare（使变得愚昧、迷恋），指使某人对某人产生不理智的热恋。',C('infatuate.s1','文学阅读','The glossy magazine profile infatuated the teenager with the singer, and he spent hours following every interview.','那篇光鲜的杂志专访让这名青少年迷上了歌手，他花了好几个小时追看每次采访。','The glossy magazine profile infatuated the teenager with the singer / and he spent hours / following every interview.','infatuate someone with someone 表示使某人迷恋某人；and 说明迷恋后的行为。','专访激起了不理智的迷恋，符合 s1。'),M('The profile infatuated the teenager with the singer by making him entirely indifferent to her and uninterested in her work.','The profile made the teenager infatuated with the singer, eager to follow her work.','完全不在意、不感兴趣与迷恋相反。'),[Q('infatuate',1,1,'To infatuate someone is to?','fill them with an unreasonable passion, usually for a person','make them calmly indifferent','give them an official induction','infatuate 指使人迷恋。'),Q('infatuate',2,1,'Which construction matches the example?','infatuate someone with a person','infatuate a person from a place','infatuate to someone about a singer','常见结构是 infatuate someone with someone。'),Q('infatuate',3,1,'A person infatuated with a singer may?','follow the singer’s interviews obsessively','feel no interest in the singer','become a metal element','迷恋可能表现为过度关注。'),Q('infatuate',4,1,'Infatuate suggests passion that is?','unreasonable or excessive','fully impartial','impossible to perceive','词条强调不理智的热情。')]);
P('infection','infection 可指病菌传播并侵入的过程，也可指由病菌造成的疾病或感染部位。',C('infection.s1','公共卫生','The clinic tracked the spread of infection by comparing weekly reports from several nearby schools.','诊所通过比较附近几所学校的每周报告，追踪感染的传播情况。','The clinic tracked the spread of infection / by comparing weekly reports / from several nearby schools.','infection 在此指病菌传播过程；by 引出追踪传播的办法。','比较多地报告以观察病菌扩散，符合 s1。'),M('The clinic called the infection’s spread a success because fewer people became ill and transmission stopped.','The clinic said the infection had declined because fewer people became ill and transmission stopped.','传播停止、患病人数减少说明感染下降，不是扩散成功。'),[Q('infection',1,1,'Infection in the process sense is?','the spread of germs that cause illness','a formal court charge','a mathematical relation','s1 指病菌传播过程。'),Q('infection',2,2,'An infection may be?','an illness caused by germs','a sign of unfair anger','a phrase ending','s2 指由病菌造成的疾病或感染部位。'),Q('infection',3,1,'A public-health team may track infection by?','comparing reports on how germs spread','counting only factory owners','checking road turn signals','比较病例报告可追踪传播。'),Q('infection',4,2,'A swollen infected area may be called?','an infection','an indication','an ineligible','s2 也指感染部位或疾病。')]);
P('inference','inference 由 infer 加 -ence 构成，可指根据证据得出的结论，也可指作出此类推断的过程。',C('inference.s1','调查分析','The investigator’s inference was that the door had been opened from inside, based on the undisturbed lock and footprints.','调查人员根据未受损的门锁和脚印推断，门是从里面打开的。','The investigator’s inference / was that the door had been opened from inside / based on the undisturbed lock / and footprints.','inference 是从证据推得的结论；that 从句陈述推断内容，based on 说明依据。','门锁与脚印构成推断依据，符合 s1。'),M('The investigator called it an inference even though it was a directly observed fact recorded on video.','The investigator called it an observation because the video showed the event directly.','视频直接记录的是观察事实，不是从证据推出来的结论。'),[Q('inference',1,1,'An inference is?','a conclusion reached by thinking about evidence','a fact stated with no evidence or reasoning','a formal induction ceremony','inference 指根据证据得出的结论。'),Q('inference',2,2,'Inference can also mean?','the act of forming a conclusion from evidence','the final written criminal charge','the process of spreading germs','s2 指推断行为本身。'),Q('inference',3,1,'Footprints and an undamaged lock may support an?','inference about how a door opened','infatuation with a singer','industrialization plan','根据痕迹形成结论属于推断。'),Q('inference',4,1,'The verb related to inference is?','infer','infest','impose','infer 表示推断。')]);
P('inferential','inferential 由 inference 加形容词后缀构成，表示通过推理得到、而非直接观察得到的。',C('inferential.s1','历史研究','The historian described the date as inferential because it was calculated from related records rather than written on the artifact.','历史学家称这个年代是推论所得，因为它是根据相关记录推算出来的，而非写在文物上。','The historian described the date as inferential / because it was calculated from related records / rather than written on the artifact.','inferential 修饰 date，表示由推理得出；because 说明结论来源。','年代是根据间接材料推得，符合 s1。'),M('The date was called inferential even though the exact date was plainly engraved on the artifact itself.','The date was directly observed because it was engraved on the artifact.','文物上直接刻出的日期不是推理所得。'),[Q('inferential',1,1,'An inferential conclusion is reached?','by reasoning rather than direct observation','by direct reading of an exact label only','through a random guess with no evidence','inferential 指凭推理得到的。'),Q('inferential',2,1,'A date calculated from related records is?','inferential','directly inscribed','a metal element','由相关记录推算属于推论。'),Q('inferential',3,1,'Inferential is an?','adjective','noun meaning a criminal charge','verb meaning to imprison','inferential 是形容词。'),Q('inferential',4,1,'The related noun is?','inference','inequality','infirmity','inferential 与 inference 同词族。')]);
P('inferiority','inferiority 由 inferior 加 -ity 构成，表示在质量、地位或能力上低于另一事物的状态。',C('inferiority.s1','产品评估','The comparison found no inferiority in the recycled material’s strength, despite its lower cost.','比较结果没有发现再生材料在强度上逊于其他材料，尽管它价格更低。','The comparison found no inferiority / in the recycled material’s strength / despite its lower cost.','inferiority in 表示某方面的低劣；no 与 despite 对比价格和质量。','测试没有发现强度较差，符合 s1 的比较义。'),M('The report found inferiority in the recycled material even though its strength matched the reference material exactly.','The report found no inferiority because its strength matched the reference material.','强度完全一致不支持“质量较差”的判断。'),[Q('inferiority',1,1,'Inferiority is the condition of being?','worse or lower than something else','equal or superior in every respect','unable to be explained','inferiority 指低劣、次等。'),Q('inferiority',2,1,'A finding of no inferiority in strength means?','the material was not weaker in that comparison','the material was proven useless','the test measured no strength','没有发现强度劣势并不等于无效。'),Q('inferiority',3,1,'Inferiority is related to the adjective?','inferior','infallible','indifferent','inferior 表示较差、较低。'),Q('inferiority',4,1,'Which phrase is natural?','inferiority in quality','inferiority by a quality of','inferiority into the quality','常用结构 inferiority in。')]);
P('infest','infest 源自拉丁语 infestare，有侵扰、攻击之意，现多指昆虫或动物大量有害地滋生在某处。',C('infest.s1','仓储检查','Mice infested the old grain store, so inspectors closed the building until it could be cleaned safely.','老粮仓里鼠类大量滋生，因此检查人员暂时关闭了建筑，直到可以安全清理。','Mice infested the old grain store / so inspectors closed the building / until it could be cleaned safely.','infest 的主语常为害虫或动物，宾语是其大量滋生的地点；so 引出处置。','鼠类大量侵扰粮仓，符合 s1。'),M('The shed was infested with pests even though no insects or animals had entered it.','The shed was pest-free because no insects or animals had entered it.','没有害虫或动物，就不能说被 infest。'),[Q('infest',1,1,'To infest a place is to?','live there in harmful numbers, as insects or animals','visit it once without staying','improve its industrial output','infest 指害虫或动物大批侵扰。'),Q('infest',2,1,'A grain store infested by mice?','has many mice living there harmfully','has no animals or insects inside','has a new indicator light','大量鼠类滋生符合该义。'),Q('infest',3,1,'Which subject commonly goes with infest?','insects or animals','a tax or fine','a mathematical expression','常见主语是虫害或动物。'),Q('infest',4,1,'What happened to the grain store?','mice were living there in harmful numbers','it was carefully disinfected already','it had become ineligible','鼠类大量滋生使粮仓受到侵扰。')]);
P('infidel','infidel 可作名词指不信奉说话者宗教的人，也可作形容词描述不接受主流或说话者信仰的；该词常带敌意。',C('infidel.s1','历史文本','The historian noted that the old chronicle used infidel as a hostile label for people outside the writer’s faith.','历史学家指出，旧编年史把 infidel 当作带敌意的称呼，用来指作者信仰之外的人。','The historian noted / that the old chronicle used infidel / as a hostile label / for people outside the writer’s faith.','infidel 在此作名词；hostile label 提示其冒犯性语气，而非中性自称。','文本中的称呼针对不属于作者信仰的人，符合 s1。'),M('The guide presented infidel as a neutral, respectful self-description used by all faith communities.','The guide explained that infidel can be a hostile label for someone outside the speaker’s religion.','词条提示该名词常带敌意，不宜说成普遍中性自称。'),[Q('infidel',1,1,'As a noun, infidel refers to?','someone rejecting the religion of the speaker','a person with a mild illness','a person who gives a formal induction','名词义指不信奉说话者宗教的人，常带敌意。'),Q('infidel',2,2,'As an adjective, infidel means?','not accepting the dominant or speaker’s faith','belonging to the speaker’s faith','unable to be distinguished','s2 是形容词义。'),Q('infidel',3,1,'How should a reader treat this term in an old text?','notice that it may be a hostile label','assume it is always a neutral self-name','use it as a medical diagnosis','该词可能具有敌意，应留意语境。'),Q('infidel',4,1,'The old chronicle uses infidel for?','people outside the writer’s faith','all members of the writer’s own faith','a type of industrialist','例句中称呼对象是作者信仰之外的人。')]);
P('infiltration','infiltration 由 infiltrate 加 -ion 构成，指秘密而逐步进入某个组织或地点的行为。',C('infiltration.s1','安全调查','The review found gradual infiltration of the shipping firm by a group seeking access to its confidential records.','审查发现，一个团体逐渐渗透进这家运输公司，试图接触其机密记录。','The review found gradual infiltration of the shipping firm / by a group / seeking access / to its confidential records.','infiltration 是名词，指逐步秘密进入；by 引出实施渗透的团体。','团体秘密进入组织并企图取得资料，符合 s1。'),M('The report called the open, announced visitor tour an infiltration even though every guest had permission and was escorted publicly.','The report called the announced, authorized tour a public visit rather than infiltration.','公开获准的参观不属于秘密逐步潜入。'),[Q('infiltration',1,1,'Infiltration is?','entering an organization or place secretly and gradually','a public visit with permission','a formal criminal verdict','infiltration 指秘密而逐步地进入。'),Q('infiltration',2,1,'Which event is infiltration?','a group quietly enters an organization to access records','a tour group enters after signing in','a staff member attends orientation','秘密进入组织符合该义。'),Q('infiltration',3,1,'Infiltration is related to the verb?','infiltrate','inflect','indite','infiltration 由 infiltrate 派生。'),Q('infiltration',4,1,'The entry in the example was?','gradual and secret','public and authorized','a type of fever','例句强调逐渐秘密进入。')]);
P('infinitesimal','infinitesimal 可作形容词表示小到难以测量，也可作名词指趋近于零的极小量。',C('infinitesimal.s1','测量比较','The new sensor detected an infinitesimal change in vibration that the older equipment could not register.','新传感器检测到了旧设备无法记录的极其微小的振动变化。','The new sensor detected an infinitesimal change / in vibration / that the older equipment / could not register.','infinitesimal 修饰 change，表示小到几乎无法测量；that 从句对比旧设备能力。','传感器发现极其细微的变化，符合 s1。'),M('The sensor recorded an infinitesimal change that was enormous, obvious, and easy to measure without instruments.','The sensor recorded a large, easily measured change.','巨大且容易测量的变化并非 infinitesimal。'),[Q('infinitesimal',1,1,'An infinitesimal change is?','exceedingly small','large enough to see from far away','certain to happen','s1 指极微小的。'),Q('infinitesimal',2,2,'In mathematics, an infinitesimal may be?','a quantity treated as approaching zero','a very large finite number','a written legal charge','s2 指趋近于零的极小量。'),Q('infinitesimal',3,1,'Which measurement is infinitesimal?','a vibration change below ordinary detection','a shift visible across the room','a large increase of several hundred units','小到普通设备无法测出的变化符合该义。'),Q('infinitesimal',4,2,'The noun sense appears in?','calculus discussions of quantities approaching zero','a list of employees','a weather report about storms','数学中讨论趋近于零的量。')]);
P('infinitesimally','infinitesimally 由 infinitesimal 加副词后缀 -ly 构成，表示变化或程度极其微小。',C('infinitesimally.s1','实验数据','The measured length differed infinitesimally between the two trials, well within the instrument’s stated margin of error.','两次试验测得的长度只有极微小差异，远在仪器标明的误差范围内。','The measured length differed infinitesimally / between the two trials / well within the instrument’s stated margin of error.','infinitesimally 修饰 differed，说明差异极小；within the margin 指其处于误差范围内。','两次测量几乎相同，符合 s1。'),M('The two measurements differed infinitesimally by several meters, a distance visible without any instrument.','The two measurements differed substantially by several meters.','数米差异非常明显，不是极微小差异。'),[Q('infinitesimally',1,1,'Infinitesimally means?','to an exceedingly small degree','by a huge amount','in a secret way','infinitesimally 指极微小地。'),Q('infinitesimally',2,1,'If two values differ infinitesimally, they are?','almost the same','far apart','impossible to compare','极微差异意味着数值几乎相同。'),Q('infinitesimally',3,1,'The adverb infinitesimally is based on?','infinitesimal','infallible','ineligible','infinitesimally 由 infinitesimal 派生。'),Q('infinitesimally',4,1,'Which sentence uses infinitesimally correctly?','The second reading was infinitesimally lower.','The second reading was infinitesimally enormous.','The second reading infinitesimal the first.','副词可修饰 lower 表示差异微小。')]);
P('infinity','infinity 源自拉丁语 infinitas（无界、无限），指空间、时间或数量没有尽头的状态。',C('infinity.s1','数学讨论','In the model, the sequence continues toward infinity rather than ending at a final largest number.','在这个模型中，数列持续趋向无穷，而不是在某个最大的数处结束。','In the model / the sequence continues toward infinity / rather than ending / at a final largest number.','infinity 作名词表示无穷；toward 引出数列延伸的方向。','数列没有最终最大值，符合 s1。'),M('The student used infinity to describe a list that stops at a fixed final number.','The student used a finite number to describe a list with a fixed end.','有固定终点的列表不是无限延伸。'),[Q('infinity',1,1,'Infinity is?','an endless extent of space, time, or quantity','a quantity with a fixed final limit','a formal charge in court','infinity 指无穷、无限。'),Q('infinity',2,1,'A sequence moving toward infinity?','does not end at a largest final number','stops at exactly ten terms','contains no numbers','趋向无穷意味着没有最终最大数。'),Q('infinity',3,1,'Which phrase is natural?','the size of the universe approaches infinity','infinity a number in every list','an infinity of fixed endings','infinity 可描述没有尽头的范围。'),Q('infinity',4,1,'The adjective related to infinity is?','infinite','indistinct','ineligible','infinite 表示无限的。')]);
P('infirm','infirm 源自拉丁语 infirmus（不强壮），形容身体虚弱、缺少体力的。',C('infirm.s1','康复支持','After a long illness, Mr. Chen felt infirm and used the handrail while walking to the community room.','久病之后，陈先生感到身体虚弱，走去活动室时扶着栏杆。','After a long illness / Mr. Chen felt infirm / and used the handrail / while walking to the community room.','infirm 作表语形容词表示体弱；and 并列说明其状态与采取的辅助方式。','久病后缺少体力、需要扶栏行走，符合 s1。'),M('The note described him as infirm even though he was physically strong and completed the long walk without difficulty.','The note described him as physically fit because he completed the walk easily.','体力充沛、轻松走完全程不符合身体虚弱。'),[Q('infirm',1,1,'An infirm person is?','physically weak and lacking strength','strong and full of energy','a person who works in a factory','infirm 指衰弱、体弱。'),Q('infirm',2,1,'After a long illness, someone may feel infirm and?','need support while walking','run effortlessly for miles','become a legal indictment','体弱者可能需要行走辅助。'),Q('infirm',3,1,'Infirm is an?','adjective','adverb meaning secretly','noun for a great number','infirm 是形容词。'),Q('infirm',4,1,'A close opposite of infirm is?','physically strong','weak','frail','physically strong 与 infirm 相反。')]);
P('infirmity','infirmity 由 infirm 加名词后缀 -ity 构成，指身体或精神上的虚弱，常与疾病或年龄有关。',C('infirmity.s1','回忆录阅读','In her memoir, the writer describes the infirmity that followed her illness and the practical support she received from friends.','作者在回忆录中描述了疾病后出现的虚弱，以及朋友提供的实际帮助。','In her memoir / the writer describes the infirmity / that followed her illness / and the practical support she received from friends.','infirmity 是表示虚弱或病患的名词；that 从句说明其来源，and 连接支持措施。','疾病之后出现的身体虚弱符合 s1。'),M('The memoir called perfect health an infirmity even though the writer had no weakness or illness.','The memoir described the writer’s weakness after illness as an infirmity.','毫无虚弱或疾病的健康状态不属于 infirmity。'),[Q('infirmity',1,1,'An infirmity is?','physical or mental weakness, often linked to age or disease','a state of perfect strength','a sudden angry feeling','infirmity 指虚弱或病患。'),Q('infirmity',2,1,'A weakness following an illness may be described as?','an infirmity','an influx','an infallible rule','疾病后虚弱符合该义。'),Q('infirmity',3,1,'Infirmity is related to the adjective?','infirm','infallible','influx','infirmity 由 infirm 派生。'),Q('infirmity',4,1,'Which phrase is natural?','an infirmity caused by illness','an infirmity of a price rise','infirmity toward a person','illness 可导致身体虚弱。')]);
P('inflammable','inflammable 源自拉丁语 inflammare（点燃），表示容易着火；另可形容容易激起强烈情绪的。',C('inflammable.s1','仓储安全','The label warns that the cleaning solvent is inflammable, so staff keep it away from heat and open flames.','标签警告这种清洁溶剂易燃，因此员工让它远离热源和明火。','The label warns / that the cleaning solvent is inflammable / so staff keep it away / from heat and open flames.','inflammable 表示容易点燃；so 引出与风险相对应的存放措施。','溶剂容易着火，符合 s1；不要把词首 in- 误解为否定。'),M('The worker assumed inflammable meant fire-resistant because it begins with in-.','The worker checked the label and treated inflammable as meaning easily set on fire.','inflammable 意为易燃；表示不易燃应使用 nonflammable。','usage'),[Q('inflammable',1,1,'An inflammable liquid?','catches fire easily','cannot catch fire under any condition','is impossible to measure','inflammable 指易燃。'),Q('inflammable',2,2,'Inflammable language may be?','easily exciting strong feelings','calming everyone completely','a type of chemical element','s2 可指易激起强烈情绪的。'),Q('inflammable',3,1,'Does the prefix-like beginning in inflammable mean “not”?','No; inflammable means easily set on fire.','Yes; it means fireproof.','It means the liquid is imported.','不能按 in- 否定前缀误解该词。'),Q('inflammable',4,1,'Which word means “not easily set on fire”?','nonflammable','inflammable','indigestible','nonflammable 表示不易燃。')]);
P('inflammation','inflammation 可指组织发红、肿胀、发热和疼痛的炎症，也可比喻突然强烈的愤怒。',C('inflammation.s1','医学词汇','The report noted inflammation around the joint, describing redness and swelling after the injury without offering a diagnosis.','报告记录了关节周围的炎症，描述受伤后的发红和肿胀，但没有作出诊断。','The report noted inflammation around the joint / describing redness and swelling / after the injury / without offering a diagnosis.','inflammation 在此指组织炎症；without 明确说明例句只记录症状，不进行诊断。','发红与肿胀符合组织炎症的描述，符合 s1。'),M('The report called the tissue inflammation even though it was cool, unswollen, and showed no redness or pain.','The report said there were no visible signs of inflammation.','没有发热、肿胀、发红或疼痛与炎症表现相反。'),[Q('inflammation',1,1,'Inflammation in tissue may involve?','redness, swelling, heat, and pain','a complete absence of symptoms','a person who supplies information','s1 是身体组织的炎症。'),Q('inflammation',2,2,'Inflammation can also mean?','a sudden strong feeling of anger','a slow rise in prices','the pitch of a voice','s2 是愤怒的比喻义。'),Q('inflammation',3,1,'Redness and swelling around a joint may be signs of?','inflammation','infinity','industrialism','这些表现符合炎症描述。'),Q('inflammation',4,2,'A speech that causes inflammation may provoke?','strong anger','a calm and neutral mood','a mathematical relation','比喻义可表示激起强烈愤怒。')]);
P('inflation','inflation 可指物价普遍持续上涨，也可指给物体充气、使其膨胀的过程。',C('inflation.s1','经济新闻','The report found that inflation had slowed, although prices were still rising more gradually than in the previous quarter.','报告发现通胀速度放缓，不过物价仍在上涨，只是比上一季度更慢。','The report found / that inflation had slowed / although prices were still rising / more gradually than in the previous quarter.','inflation 在此指物价普遍上涨；slowed 表示涨幅速度降低，并不表示价格整体下降。','物价仍上涨但速度降低，符合 s1。'),M('The article said inflation had ended because prices were still rising steadily across the economy.','The article said inflation continued because prices were still rising steadily.','物价持续普遍上涨说明通胀仍在发生。'),[Q('inflation',1,1,'Economic inflation is?','a general and steady rise in prices','a general and steady fall in prices','a formal charge against someone','s1 指通货膨胀。'),Q('inflation',2,2,'Inflation of a tire is?','the act of filling it with air','a rise in food prices','a legal indictment','s2 指充气、膨胀。'),Q('inflation',3,1,'If inflation slows but prices still rise, then?','prices are rising more slowly','prices must be falling','the economy has no prices','通胀放缓不等于价格下降。'),Q('inflation',4,2,'A pump helps with?','inflation of a tire','indignation at unfairness','an inference from data','气泵给轮胎充气。')]);
P('inflection','inflection 可指显示时态、数或格的词形变化，也可指说话时音高的升降变化。',C('inflection.s2','口语表达','Her voice inflection rose at the end of the question, making the sentence sound genuinely curious.','她在问句结尾提高了音调，使整句话听起来确实带有好奇。','Her voice inflection rose / at the end of the question / making the sentence / sound genuinely curious.','inflection 在此指音高变化；making 补充音调变化造成的听感。','问句末尾音高上扬，符合 s2。'),M('The speaker’s inflection never changed in pitch, yet the note described it as a rise and fall in her voice.','The note described the speaker’s tone as flat because its pitch did not change.','音高不变是平直语调，不是升降变化。'),[Q('inflection',1,1,'A grammatical inflection may show?','tense, number, or case','a person’s job title','a rise in product prices','s1 指词形变化。'),Q('inflection',2,2,'Voice inflection is a change in?','the pitch of someone’s voice','a noun’s spelling only','the number of imported goods','s2 指语调音高升降。'),Q('inflection',3,2,'A rising inflection at a question’s end may make it sound?','curious or questioning','like a fixed written suffix','chemically inert','语调上扬可以呈现疑问或好奇。'),Q('inflection',4,1,'Adding -s to mark plural is an example of?','grammatical inflection','voice inflection','inflation','词尾变化标记数属于语法屈折。')]);
P('inflexibly','inflexibly 由 inflexible 加副词后缀 -ly 构成，表示毫不愿意改变规则、立场或意见地。',C('inflexibly.s1','机构规则','The office applied the deadline inflexibly, even when a documented transit shutdown prevented applicants from arriving.','即使有记录证明交通停运导致申请人无法到场，办公室仍毫不通融地执行截止时间。','The office applied the deadline inflexibly / even when a documented transit shutdown / prevented applicants / from arriving.','inflexibly 修饰 applied，表示执行时不愿调整；even when 引出特殊情况。','规则没有因明确障碍作出任何调整，符合 s1。'),M('The office applied the rule inflexibly by readily changing it for every applicant who asked.','The office applied the rule flexibly because it adjusted it when warranted.','主动根据情况调整规则是灵活执行，不是 inflexibly。'),[Q('inflexibly',1,1,'To act inflexibly is to act?','without willingness to alter a rule or opinion','readily adapting to new circumstances','in an indistinct voice','inflexibly 指毫不妥协地。'),Q('inflexibly',2,1,'An office applies a deadline inflexibly when it?','refuses to adjust it even in special circumstances','changes it readily when needed','does not set any deadline','不作调整体现毫不通融。'),Q('inflexibly',3,1,'The adverb inflexibly is related to?','inflexible','inflow','infection','inflexibly 来自 inflexible。'),Q('inflexibly',4,1,'A close opposite of inflexibly is?','flexibly','rigidly','uncompromisingly','flexibly 表示灵活地。')]);
P('inflow','inflow 由 in 与 flow 组合构成，指水、资金或其他事物流入某个系统或地点。',C('inflow.s1','水库管理','The reservoir’s inflow increased after several days of rain, giving the water managers more room to plan releases.','连续降雨后水库的流入水量增加，让水务人员有了更多调度空间。','The reservoir’s inflow increased / after several days of rain / giving the water managers / more room to plan releases.','inflow 指流入某处的水量或过程；after 引出流量增加的时间原因。','雨水进入水库形成的流入量增加，符合 s1。'),M('The report called water leaving the reservoir its inflow.','The report called water entering the reservoir its inflow and water leaving it its outflow.','离开水库的是 outflow，进入水库的才是 inflow。'),[Q('inflow',1,1,'Inflow is?','the arrival of something into a system or place','the departure of something from it','a group of people who provide secret facts','inflow 指流入或流入量。'),Q('inflow',2,1,'Rainwater entering a reservoir increases its?','inflow','outflow','inflection','进入水库的水属于 inflow。'),Q('inflow',3,1,'Which is an inflow of funds?','money arriving in an account','money paid out of an account','a change in voice pitch','资金进入系统属于 inflow。'),Q('inflow',4,1,'The prefix in- in inflow points to movement?','into a place','out of a place','between two speakers','in- 表示向内流入。')]);
P('influx','influx 源自拉丁语 influxus（流入），指大量人员或事物涌入某处。',C('influx.s1','节庆活动','The town prepared for an influx of visitors during the spring festival by adding temporary bus services.','小镇为春季节庆期间大量游客涌入作准备，增设了临时公交服务。','The town prepared for an influx of visitors / during the spring festival / by adding temporary bus services.','influx of people 表示大量人员涌入；by 引出应对方式。','节庆期间游客大量到来，符合 s1。'),M('The town described three departing visitors as an influx even though no new people arrived.','The town described the small departure as an outflow rather than an influx.','离开而非涌入，与 influx 的方向相反。'),[Q('influx',1,1,'An influx is?','the arrival of many people or a large amount of something','the departure of one person','a single legal charge','influx 指大量涌入。'),Q('influx',2,1,'A festival influx may require?','extra transport for arriving visitors','closing all transport because nobody came','a new mathematical inequality','大量游客到来需要额外交通安排。'),Q('influx',3,1,'Which phrase is natural?','an influx of visitors','an influx out of visitors','the influx for leaving visitors','常用搭配 influx of。'),Q('influx',4,1,'A large influx of water into a lake means?','a lot of water is flowing in','water is draining away','the lake has no water','大量水流入符合 influx。')]);
P('informant','informant 由 inform 加 -ant 构成，指向他人提供事实或消息的人，尤指秘密向当局提供信息者。',C('informant.s1','环境调查','An informant shared records of illegal dumping with investigators, who then checked the claims against public inspection logs.','一名消息提供者向调查人员分享了非法倾倒的记录，调查人员随后用公开检查日志核实这些说法。','An informant shared records of illegal dumping / with investigators / who then checked the claims / against public inspection logs.','informant 指提供信息的人；who 从句说明调查人员如何核实消息。','当事人向调查人员提供事实，符合 s1；例句强调独立核验。'),M('The witness was called an informant even though they supplied no information or facts to anyone.','The witness was called an informant because they supplied records to investigators.','没有提供任何消息或事实，就不符合 informant 的定义。'),[Q('informant',1,1,'An informant is someone who?','supplies facts or information, sometimes secretly to authorities','is formally charged with a crime','cannot be distinguished from another person','informant 指消息提供者。'),Q('informant',2,1,'In an investigation, an informant may?','share information with authorities','decide a court verdict','issue a traffic indication','消息提供者可向当局提供信息。'),Q('informant',3,1,'The suffix -ant in informant identifies?','a person who performs or supplies something','a state of being poor','an adverbial degree','-ant 可构成表示人的名词。'),Q('informant',4,1,'Why did investigators check the informant’s records?','to verify the claims independently','to treat every claim as proven','to increase inflation','独立核实可确认消息可靠性。')]);

})();
